  resetMetrics(): void {
    this.requestCount = 0;
    this.validationCount = 0;
    this.averageProcessingTime = 0;
    this.tasksProcessed = 0;
    this.autonomousExecutions = 0;
    this.logger.log('Tasks AI Service metrics reset');
