  readonly validationDetails: {
    approved: boolean;
    conversationId: string;
    taskRisk: RiskLevel;
    executionConstraints: TaskExecutionConstraints;
    securityValidation: {
      passed: boolean;
      flags: string[];
      recommendations: string[];
    };
