  }

  /**
   * Create timeout promise for execution limits
   */
  private createTimeoutPromise(timeoutMs: number): Promise<never> {
    return new Promise((_, reject) => {
      setTimeout(() => {
        reject(new Error(`Task operation timed out after ${timeoutMs}ms`));
      }, timeoutMs);
    });
  }

  /**
