 * @version 1.0.0
 * @author Input Validation & API Security Specialist
 */

// TypeScript safety note: This file uses flexible typing for NestJS integration

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { ThrottlerException } from '@nestjs/throttler';

/**
 * Security-focused error classification
 */
enum SecurityErrorType {
  VALIDATION_ERROR = 'validation_error',
  AUTHENTICATION_ERROR = 'authentication_error',
  AUTHORIZATION_ERROR = 'authorization_error',
  RATE_LIMIT_ERROR = 'rate_limit_error',
  SECURITY_VIOLATION = 'security_violation',
  SYSTEM_ERROR = 'system_error',
  INPUT_ERROR = 'input_error',
}

/**
 * Secure error response structure
 */
interface SecureErrorResponse {
  statusCode: number;
  error: string;
  message: string;
  timestamp: string;
  path: string;
  requestId: string;
  // Only include in development
  details?: any;
  stack?: string;
}

/**
 * Security metrics for error tracking
 */
interface _SecurityErrorMetrics {
  errorType: SecurityErrorType;
  statusCode: number;
  clientIP: string;
  userAgent: string;
  endpoint: string;
  timestamp: Date;
  riskScore: number;
}

@Catch()
export class SecurityExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(SecurityExceptionFilter.name);

  // Track error patterns for security analysis
  private errorPatterns = new Map<
    string,
    {
      count: number;
      lastSeen: Date;
      riskScore: number;
    }
  >();

  /**
   * Handle all exceptions with security-focused processing
   */
  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const request = ctx.getRequest<Request>();
    const response = ctx.getResponse<Response>();

    // Generate request ID for tracking (use existing or create new)
    const requestId =
      (request.headers['x-correlation-id'] as string) ||
      (request.headers['x-request-id'] as string) ||
      `error-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    // Classify and analyze the exception
    const errorAnalysis = this.analyzeException(exception, request);

    // Create secure error response (never leak sensitive info)
    const secureResponse = this.createSecureResponse(
      exception,
      request,
      requestId,
      errorAnalysis,
    );

    // Log security event with full details (for internal use)
    this.logSecurityEvent(exception, request, errorAnalysis, requestId);

    // Track error patterns for threat detection
    this.trackErrorPattern(request, errorAnalysis);

    // Check for security attack patterns
    if (errorAnalysis.riskScore >= 7) {
      this.handleHighRiskError(request, errorAnalysis, requestId);
    }

    // Set security headers
    response.setHeader('X-Request-ID', requestId);
    response.setHeader('X-Content-Type-Options', 'nosniff');
    response.setHeader('X-Frame-Options', 'DENY');

    // Send secure response
    response.status(secureResponse.statusCode).json(secureResponse);
  }

  /**
   * Analyze exception for security classification and risk assessment
   */
  private analyzeException(
    exception: unknown,
    request: Request,
  ): {
    errorType: SecurityErrorType;
    statusCode: number;
    riskScore: number;
    threatIndicators: string[];
    isSecurityRelated: boolean;
  } {
    let errorType = SecurityErrorType.SYSTEM_ERROR;
    let statusCode = HttpStatus.INTERNAL_SERVER_ERROR;
    let riskScore = 1;
    const threatIndicators: string[] = [];

    // Analyze exception type
    if (exception instanceof HttpException) {
      statusCode = exception.getStatus();

      // Classify by HTTP status code
      switch (statusCode) {
        case HttpStatus.BAD_REQUEST:
          errorType = SecurityErrorType.INPUT_ERROR;
          riskScore = 2;
          break;
        case HttpStatus.UNAUTHORIZED:
          errorType = SecurityErrorType.AUTHENTICATION_ERROR;
          riskScore = 4;
          threatIndicators.push('auth_failure');
          break;
        case HttpStatus.FORBIDDEN:
          errorType = SecurityErrorType.AUTHORIZATION_ERROR;
          riskScore = 5;
          threatIndicators.push('access_denied');
          break;
        case HttpStatus.TOO_MANY_REQUESTS:
          errorType = SecurityErrorType.RATE_LIMIT_ERROR;
          riskScore = 3;
          threatIndicators.push('rate_limit_exceeded');
          break;
        default:
          if (statusCode >= 400 && statusCode < 500) {
            riskScore = 3;
          }
      }

      // Check for specific exception types
      if (exception instanceof ThrottlerException) {
        errorType = SecurityErrorType.RATE_LIMIT_ERROR;
        riskScore = 4;
        threatIndicators.push('throttle_violation');
      }

      // Analyze error message for security patterns
      const message = exception.message?.toLowerCase() ?? '';

      if (message.includes('validation') ?? message.includes('sanitization')) {
        errorType = SecurityErrorType.VALIDATION_ERROR;
        riskScore += 1;
      }

      if (
        message.includes('xss') ||
        message.includes('injection') ||
        message.includes('malicious')
      ) {
        errorType = SecurityErrorType.SECURITY_VIOLATION;
        riskScore += 4;
        threatIndicators.push('attack_detected');
      }
    }

    // Increase risk score for repeated errors from same client
    const clientIdentifier = this.getClientIdentifier(request);
    const existingPattern = this.errorPatterns.get(clientIdentifier);
    if (existingPattern && existingPattern.count > 5) {
      riskScore += 2;
      threatIndicators.push('repeated_errors');
    }

    return {
      errorType,
      statusCode,
      riskScore: Math.min(10, riskScore), // Cap at 10
      threatIndicators,
      isSecurityRelated: riskScore >= 4 || threatIndicators.length > 0,
    };
  }

  /**
   * Create secure error response that doesn't leak sensitive information
   */
  private createSecureResponse(
    exception: unknown,
    request: Request,
    requestId: string,
    errorAnalysis: {
      errorType: SecurityErrorType;
      statusCode: number;
      riskScore: number;
      threatIndicators: string[];
      isSecurityRelated: boolean;
    },
  ): SecureErrorResponse {
    const isDevelopment = process.env.NODE_ENV === 'development';

    // Base secure response
    const response: SecureErrorResponse = {
      statusCode: errorAnalysis.statusCode,
      error: this.getSecureErrorName(errorAnalysis.statusCode),
      message: this.getSecureErrorMessage(exception, errorAnalysis),
      timestamp: new Date().toISOString(),
      path: request.path,
      requestId,
    };

    // Only include detailed information in development
    if (isDevelopment) {
      response.details = this.sanitizeErrorDetails(exception);

      if (exception instanceof Error && exception.stack) {
        response.stack = exception.stack;
      }
    }

    return response;
  }

  /**
   * Get secure error name based on status code
   */
  private getSecureErrorName(statusCode: number): string {
    const errorNames: Record<number, string> = {
      400: 'Bad Request',
      401: 'Unauthorized',
      403: 'Forbidden',
      404: 'Not Found',
      405: 'Method Not Allowed',
      409: 'Conflict',
      422: 'Unprocessable Entity',
      429: 'Too Many Requests',
      500: 'Internal Server Error',
      502: 'Bad Gateway',
      503: 'Service Unavailable',
      504: 'Gateway Timeout',
    };

    return errorNames[statusCode] ?? 'Unknown Error';
  }

  /**
   * Get secure error message that doesn't leak sensitive information
   */
  private getSecureErrorMessage(
    exception: unknown,
    errorAnalysis: {
      errorType: SecurityErrorType;
      statusCode: number;
      riskScore: number;
      threatIndicators: string[];
      isSecurityRelated: boolean;
    },
  ): string {
    // For security violations, use generic message
    if (errorAnalysis.errorType === SecurityErrorType.SECURITY_VIOLATION) {
      return 'Request blocked due to security policy violation';
    }

    // For rate limiting
    if (errorAnalysis.errorType === SecurityErrorType.RATE_LIMIT_ERROR) {
      return 'Too many requests. Please try again later';
    }

    // For validation errors, provide safe message
    if (errorAnalysis.errorType === SecurityErrorType.VALIDATION_ERROR) {
      return 'Invalid input provided. Please check your request';
    }

    // For HTTP exceptions, use the message but sanitize it
    if (exception instanceof HttpException) {
      const message = exception.message;
      return this.sanitizeErrorMessage(message);
    }

    // Generic message for other errors
    return 'An error occurred while processing your request';
  }

  /**
   * Sanitize error message to prevent information disclosure
   */
  private sanitizeErrorMessage(message: string): string {
    // Remove sensitive patterns
    const sanitizedMessage = message
      // Remove file paths
      .replace(/\/[a-zA-Z0-9/_-]+/g, '[PATH_REMOVED]')
      // Remove database information
      .replace(/database|table|column|sql|query/gi, '[DB_INFO_REMOVED]')
      // Remove system information
      .replace(/system|process|memory|cpu/gi, '[SYSTEM_INFO_REMOVED]')
      // Remove stack traces
      .replace(/at [a-zA-Z0-9._]+\([^)]+\)/g, '[STACK_REMOVED]')
      // Remove sensitive environment variables
      .replace(
        /NODE_ENV|API_KEY|SECRET|PASSWORD|TOKEN/gi,
        '[SENSITIVE_REMOVED]',
      );

    return sanitizedMessage.substring(0, 200); // Limit message length
  }

  /**
   * Sanitize error details for development responses
   */
  private sanitizeErrorDetails(exception: unknown): any {
    if (!(exception instanceof Error)) {
      return null;
    }

    return {
      name: exception.name,
      cause: (exception as any).cause ?? 'Unknown',
      // Don't include the full stack trace in JSON response
    };
  }

  /**
   * Log security event with full details for monitoring
   */
  private logSecurityEvent(
    exception: unknown,
    request: Request,
    errorAnalysis: {
      errorType: SecurityErrorType;
      statusCode: number;
      riskScore: number;
      threatIndicators: string[];
      isSecurityRelated: boolean;
    },
    requestId: string,
  ): void {
    const logData = {
      event: 'security_exception',
      requestId,
      errorType: errorAnalysis.errorType,
      statusCode: errorAnalysis.statusCode,
      riskScore: errorAnalysis.riskScore,
      threatIndicators: errorAnalysis.threatIndicators,
      isSecurityRelated: errorAnalysis.isSecurityRelated,
      request: {
        method: request.method,
        url: request.url,
        path: request.path,
        query: request.query,
        headers: this.sanitizeHeaders(request.headers),
        clientIP: this.getClientIP(request),
        userAgent: request.headers['user-agent'],
      },
      exception: {
        name: exception instanceof Error ? exception.name : 'Unknown',
        message:
          exception instanceof Error ? exception.message : String(exception),
        stack: exception instanceof Error ? exception.stack : undefined,
      },
      timestamp: new Date().toISOString(),
    };

    // Log at appropriate level based on risk score
    if (errorAnalysis.riskScore >= 7) {
      this.logger.error(`[${requestId}] HIGH RISK SECURITY EXCEPTION`, logData);
    } else if (errorAnalysis.isSecurityRelated) {
      this.logger.warn(`[${requestId}] Security-related exception`, logData);
    } else {
      this.logger.debug(`[${requestId}] Application exception`, logData);
    }
  }

  /**
   * Track error patterns for threat detection
   */
  private trackErrorPattern(
    request: Request,
    errorAnalysis: {
      errorType: SecurityErrorType;
      statusCode: number;
      riskScore: number;
      threatIndicators: string[];
      isSecurityRelated: boolean;
    },
  ): void {
    const clientIdentifier = this.getClientIdentifier(request);
    const now = new Date();

    if (!this.errorPatterns.has(clientIdentifier)) {
      this.errorPatterns.set(clientIdentifier, {
        count: 1,
        lastSeen: now,
        riskScore: errorAnalysis.riskScore,
      });
    } else {
      const pattern = this.errorPatterns.get(clientIdentifier);
      if (!pattern) {
        return; // Should not happen due to the check above, but being type-safe
      }
      pattern.count += 1;
      pattern.lastSeen = now;
      pattern.riskScore = Math.max(pattern.riskScore, errorAnalysis.riskScore);
    }

    // Clean up old patterns (older than 1 hour)
    this.cleanupErrorPatterns();
  }

  /**
   * Handle high-risk security errors
   */
  private handleHighRiskError(
    request: Request,
    errorAnalysis: {
      errorType: SecurityErrorType;
      statusCode: number;
      riskScore: number;
      threatIndicators: string[];
      isSecurityRelated: boolean;
    },
    requestId: string,
  ): void {
    const clientIP = this.getClientIP(request);
    const userAgent = request.headers['user-agent'];

    this.logger.error(`[${requestId}] HIGH RISK SECURITY EVENT DETECTED`, {
      event: 'high_risk_error',
      requestId,
      clientIP,
      userAgent,
      endpoint: request.path,
      riskScore: errorAnalysis.riskScore,
      threatIndicators: errorAnalysis.threatIndicators,
      recommendation:
        'Consider implementing additional security measures for this client',
      timestamp: new Date().toISOString(),
    });

    // In a production environment, you might:
    // - Send alert to security team
    // - Add IP to temporary blocklist
    // - Increase monitoring for this client
    // - Trigger additional security measures
  }

  /**
   * Generate client identifier for tracking
   */
  private getClientIdentifier(request: Request): string {
    const ip = this.getClientIP(request);
    const userAgent = (request.headers['user-agent'] ?? '').substring(0, 50);
    return `${ip}:${userAgent}`.replace(/[^a-zA-Z0-9:.-]/g, '_');
  }

  /**
   * Get client IP address
   */
  private getClientIP(request: Request): string {
    return (
      (request.headers['x-forwarded-for'] as string)?.split(',')[0] ??
      (request.headers['x-real-ip'] as string) ??
      request.connection.remoteAddress ??
      request.socket.remoteAddress ??
      'unknown'
    );
  }

  /**
   * Sanitize headers to remove sensitive information
   */
  private sanitizeHeaders(headers: any): any {
    const sanitized = { ...headers };

    const sensitiveHeaders = [
      'authorization',
      'cookie',
      'x-api-key',
      'x-auth-token',
      'proxy-authorization',
    ];

    sensitiveHeaders.forEach((header) => {
      if (sanitized[header]) {
        sanitized[header] = '[REDACTED]';
      }
    });

    return sanitized;
  }

  /**
   * Clean up old error patterns
   */
  private cleanupErrorPatterns(): void {
    const now = Date.now();
    const maxAge = 60 * 60 * 1000; // 1 hour

    // Convert to array to avoid iterator issues
    const entries = Array.from(this.errorPatterns.entries());
    for (const [key, pattern] of entries) {
      if (now - pattern.lastSeen.getTime() > maxAge) {
        this.errorPatterns.delete(key);
      }
    }
  }

  /**
   * Get current error pattern statistics (for monitoring)
   */
  getErrorPatternStats(): {
    totalClients: number;
    highRiskClients: number;
    topErrorClients: Array<{
      client: string;
      count: number;
      riskScore: number;
      lastSeen: Date;
    }>;
  } {
    const highRiskClients = Array.from(this.errorPatterns.entries()).filter(
      ([, pattern]) => pattern.riskScore >= 6,
    ).length;

    const topErrorClients = Array.from(this.errorPatterns.entries())
      .sort(([, a], [, b]) => b.count - a.count)
      .slice(0, 10)
      .map(([client, pattern]) => ({
        client: client.substring(0, 30) + '...', // Truncate for privacy
        count: pattern.count,
        riskScore: pattern.riskScore,
        lastSeen: pattern.lastSeen,
      }));

    return {
      totalClients: this.errorPatterns.size,
      highRiskClients,
      topErrorClients,
    };
  }
}

/**
 * Compression Interceptor - Response Compression for Performance
 *
 * Provides intelligent response compression with support for multiple
 * compression algorithms (gzip, brotli, deflate). Automatically selects
 * optimal compression based on content type, size, and client support.
 *
 * Features:
 * - Multi-algorithm support (gzip, brotli, deflate)
 * - Content-type specific compression rules
 * - Minimum size thresholds for efficiency
 * - Client capability detection
 * - Compression ratio metrics
 * - Performance impact monitoring
 * - Configurable compression levels
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, mergeMap, from } from 'rxjs';
import { Request, Response } from 'express';
import { gzip, brotliCompress, deflate } from 'zlib';
import { promisify } from 'util';
import { MetricsService } from '../../metrics/metrics.service';

// Promisify compression functions
const gzipAsync = promisify(gzip);
const brotliCompressAsync = promisify(brotliCompress);
const deflateAsync = promisify(deflate);

/**
 * Compression algorithm types
 */
type CompressionAlgorithm = 'gzip' | 'brotli' | 'deflate' | 'identity';

/**
 * Compression configuration
 */
interface CompressionConfig {
  minSize: number; // Minimum response size to compress (bytes)
  level: number; // Compression level (1-9 for gzip/deflate, 1-11 for brotli)
  threshold: number; // Minimum compression ratio to use compression
  compressibleTypes: Set<string>; // Content types that should be compressed
  maxSize: number; // Maximum response size to compress (bytes)
}

/**
 * Compression statistics
 */
interface CompressionStats {
  totalRequests: number;
  compressedRequests: number;
  compressionRatio: number;
  bytesOriginal: number;
  bytesCompressed: number;
  averageCompressionTime: number;
  algorithmUsage: Record<CompressionAlgorithm, number>;
}

/**
 * Compression result for a single response
 */
interface CompressionResult {
  algorithm: CompressionAlgorithm;
  originalSize: number;
  compressedSize: number;
  ratio: number;
  compressionTime: number;
  applied: boolean;
}

/**
 * Response compression interceptor
 */
@Injectable()
export class CompressionInterceptor implements NestInterceptor {
  private readonly logger = new Logger(CompressionInterceptor.name);
  private readonly stats: CompressionStats = {
    totalRequests: 0,
    compressedRequests: 0,
    compressionRatio: 0,
    bytesOriginal: 0,
    bytesCompressed: 0,
    averageCompressionTime: 0,
    algorithmUsage: {
      gzip: 0,
      brotli: 0,
      deflate: 0,
      identity: 0,
    },
  };

  // Compression configuration (configurable via environment variables)
  private readonly config: CompressionConfig = {
    minSize: parseInt(process.env.COMPRESSION_MIN_SIZE ?? '1024', 10), // 1KB
    level: parseInt(process.env.COMPRESSION_LEVEL ?? '6', 10), // Balanced compression
    threshold: parseFloat(process.env.COMPRESSION_THRESHOLD ?? '0.8'), // 20% minimum reduction
    maxSize: parseInt(process.env.COMPRESSION_MAX_SIZE ?? '10485760', 10), // 10MB
    compressibleTypes: new Set([
      'application/json',
      'application/javascript',
      'application/xml',
      'text/plain',
      'text/html',
      'text/css',
      'text/javascript',
      'text/xml',
      'image/svg+xml',
    ]),
  };

  constructor(private readonly metricsService?: MetricsService) {
    this.logger.log('Compression Interceptor initialized');
    this.logger.log(
      `Config: minSize=${this.config.minSize}b, level=${this.config.level}, threshold=${this.config.threshold}`,
    );

    // Start periodic stats reporting
    this.startPeriodicReporting();
  }

  /**
   * Intercept HTTP responses to apply compression
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<Request>();
    const response = context.switchToHttp().getResponse<Response>();

    return next.handle().pipe(
      mergeMap((data: unknown) => {
        return from(this.handleCompressionAsync(data, request, response));
      }),
    );
  }

  /**
   * Handle compression asynchronously with proper type safety
   */
  private async handleCompressionAsync(
    data: unknown,
    request: Request,
    response: Response,
  ): Promise<unknown> {
    // Skip compression if already handled by middleware
    if (response.get('Content-Encoding')) {
      this.updateStats({
        algorithm: 'identity',
        originalSize: 0,
        compressedSize: 0,
        ratio: 1,
        compressionTime: 0,
        applied: false,
      });
      return data;
    }

    // Compress response if applicable
    const compressionResult = await this.compressResponse(
      data,
      request,
      response,
    );

    if (
      compressionResult.applied &&
      compressionResult.algorithm !== 'identity'
    ) {
      // Set compression headers
      response.set('Content-Encoding', compressionResult.algorithm);
      response.set('Vary', 'Accept-Encoding');

      this.logger.debug(
        `Response compressed: ${compressionResult.algorithm}, ` +
          `${compressionResult.originalSize}b → ${compressionResult.compressedSize}b ` +
          `(${(compressionResult.ratio * 100).toFixed(1)}% reduction)`,
      );
    }

    this.updateStats(compressionResult);
    return data;
  }

  /**
   * Compress response data with optimal algorithm selection
   */
  private async compressResponse(
    data: unknown,
    request: Request,
    response: Response,
  ): Promise<CompressionResult> {
    const operationId =
      (request as Request & { operationId?: string }).operationId ??
      `compress_${Date.now()}`;
    const startTime = Date.now();

    try {
      // Convert data to buffer for processing
      const responseBuffer = this.dataToBuffer(data);
      const originalSize = responseBuffer.length;

      // Check if compression should be applied
      if (!this.shouldCompress(responseBuffer, response)) {
        return {
          algorithm: 'identity',
          originalSize,
          compressedSize: originalSize,
          ratio: 1,
          compressionTime: 0,
          applied: false,
        };
      }

      // Determine best compression algorithm
      const algorithm = this.selectCompressionAlgorithm(request);

      // Apply compression
      const compressedData = await this.applyCompression(
        responseBuffer,
        algorithm,
      );
      const compressedSize = compressedData.length;
      const ratio = compressedSize / originalSize;

      // Check if compression is beneficial
      if (ratio > this.config.threshold) {
        // Compression not beneficial enough
        return {
          algorithm: 'identity',
          originalSize,
          compressedSize: originalSize,
          ratio: 1,
          compressionTime: Date.now() - startTime,
          applied: false,
        };
      }

      // Set compressed data as response
      response.send(compressedData);

      return {
        algorithm,
        originalSize,
        compressedSize,
        ratio,
        compressionTime: Date.now() - startTime,
        applied: true,
      };
    } catch (_error) {
      const compressionTime = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Compression failed: ${errorMessage} (${compressionTime}ms)`,
      );

      // Return uncompressed data on error
      return {
        algorithm: 'identity',
        originalSize: this.dataToBuffer(data).length,
        compressedSize: this.dataToBuffer(data).length,
        ratio: 1,
        compressionTime,
        applied: false,
      };
    }
  }

  /**
   * Determine if response should be compressed
   */
  private shouldCompress(data: Buffer, response: Response): boolean {
    // Check minimum size
    if (data.length < this.config.minSize) {
      return false;
    }

    // Check maximum size
    if (data.length > this.config.maxSize) {
      return false;
    }

    // Check content type
    const contentType = response.get('Content-Type') ?? '';
    const baseType = contentType.split(';')[0]?.toLowerCase() ?? '';

    return this.config.compressibleTypes.has(baseType);
  }

  /**
   * Select optimal compression algorithm based on client support
   */
  private selectCompressionAlgorithm(request: Request): CompressionAlgorithm {
    const acceptEncoding = request.get('Accept-Encoding') ?? '';

    // Priority order: brotli (best compression) → gzip (widely supported) → deflate
    if (acceptEncoding.includes('br')) {
      return 'brotli';
    } else if (acceptEncoding.includes('gzip')) {
      return 'gzip';
    } else if (acceptEncoding.includes('deflate')) {
      return 'deflate';
    } else {
      return 'identity';
    }
  }

  /**
   * Apply compression using specified algorithm
   */
  private async applyCompression(
    data: Buffer,
    algorithm: CompressionAlgorithm,
  ): Promise<Buffer> {
    switch (algorithm) {
      case 'brotli':
        return await brotliCompressAsync(data, {
          params: {
            [require('zlib').constants.BROTLI_PARAM_QUALITY]: this.config.level,
          },
        });

      case 'gzip':
        return await gzipAsync(data, { level: this.config.level });

      case 'deflate':
        return await deflateAsync(data, { level: this.config.level });

      default:
        return data;
    }
  }

  /**
   * Convert response data to buffer
   */
  private dataToBuffer(data: unknown): Buffer {
    if (Buffer.isBuffer(data)) {
      return data;
    }

    if (typeof data === 'string') {
      return Buffer.from(data, 'utf8');
    }

    if (typeof data === 'object') {
      return Buffer.from(JSON.stringify(data), 'utf8');
    }

    return Buffer.from(String(data), 'utf8');
  }

  /**
   * Update compression statistics
   */
  private updateStats(result: CompressionResult): void {
    try {
      this.stats.totalRequests++;

      if (result.applied && result.algorithm !== 'identity') {
        this.stats.compressedRequests++;
        this.stats.bytesOriginal += result.originalSize;
        this.stats.bytesCompressed += result.compressedSize;

        // Update average compression time
        this.stats.averageCompressionTime =
          (this.stats.averageCompressionTime *
            (this.stats.compressedRequests - 1) +
            result.compressionTime) /
          this.stats.compressedRequests;
      } else {
        this.stats.bytesOriginal += result.originalSize;
        this.stats.bytesCompressed += result.originalSize; // No compression applied
      }

      // Update algorithm usage
      this.stats.algorithmUsage[result.algorithm]++;

      // Calculate overall compression ratio
      if (this.stats.bytesOriginal > 0) {
        this.stats.compressionRatio =
          (this.stats.bytesOriginal - this.stats.bytesCompressed) /
          this.stats.bytesOriginal;
      }

      // Record metrics
      if (this.metricsService) {
        this.metricsService.recordCompressionMetrics?.(
          result.algorithm,
          result.originalSize,
          result.compressedSize,
          result.compressionTime,
        );
      }
    } catch (_error) {
      this.logger.error(
        `Failed to update compression statistics: ${_error instanceof Error ? _error.message : 'Unknown _error'}`,
      );
    }
  }

  /**
   * Get current compression statistics
   */
  getStats(): CompressionStats {
    return {
      ...this.stats,
      algorithmUsage: { ...this.stats.algorithmUsage },
    };
  }

  /**
   * Clear compression statistics
   */
  clearStats(): void {
    Object.assign(this.stats, {
      totalRequests: 0,
      compressedRequests: 0,
      compressionRatio: 0,
      bytesOriginal: 0,
      bytesCompressed: 0,
      averageCompressionTime: 0,
      algorithmUsage: {
        gzip: 0,
        brotli: 0,
        deflate: 0,
        identity: 0,
      },
    });

    this.logger.log('Compression statistics cleared');
  }

  /**
   * Start periodic statistics reporting
   */
  private startPeriodicReporting(): void {
    // Report compression stats every 10 minutes
    setInterval(() => {
      if (this.stats.totalRequests > 0) {
        this.logger.log('Compression Statistics Summary:', {
          totalRequests: this.stats.totalRequests,
          compressedRequests: this.stats.compressedRequests,
          compressionRate: `${((this.stats.compressedRequests / this.stats.totalRequests) * 100).toFixed(1)}%`,
          overallCompressionRatio: `${(this.stats.compressionRatio * 100).toFixed(1)}%`,
          bytesSaved: `${((this.stats.bytesOriginal - this.stats.bytesCompressed) / 1024 / 1024).toFixed(2)}MB`,
          averageCompressionTime: `${this.stats.averageCompressionTime.toFixed(2)}ms`,
          algorithmUsage: this.stats.algorithmUsage,
        });
      }
    }, 600000); // 10 minutes
  }
}

/**
 * Logging Interceptor with Correlation ID Tracking
 *
 * NestJS interceptor providing comprehensive request/response logging with
 * correlation ID tracking for enterprise-grade observability. Enables
 * distributed tracing and structured JSON logging.
 *
 * Features:
 * - Correlation ID generation and propagation
 * - Structured JSON logging format
 * - Request/response timing
 * - Error tracking with stack traces
 * - Performance metrics integration
 * - User context tracking
 *
 * @author Claude Code
 * @version 1.0.0
 */

// TypeScript safety note: This file uses flexible typing for NestJS integration

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Observable, throwError } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';

// Type definitions for explicit any type replacement
interface HttpErrorWithStatus {
  status?: number;
  statusCode?: number;
  message?: string;
  name?: string;
  stack?: string;
}

interface RequestWithPath {
  path?: string;
  url?: string;
  method?: string;
  [key: string]: unknown;
}
import { Request, Response } from 'express';
import { v4 as _uuidv4 } from 'uuid';
import { MetricsService } from '../../metrics/metrics.service';

/**
 * Request context interface for structured logging
 */
export interface RequestContext {
  correlationId: string;
  method: string;
  url: string;
  userAgent?: string;
  remoteAddress: string;
  timestamp: string;
  userId?: string;
  sessionId?: string;
}

/**
 * Response context interface for structured logging
 */
export interface ResponseContext {
  statusCode: number;
  processingTime: number;
  contentLength?: number;
  cacheHit?: boolean;
}

/**
 * Error context interface for structured logging
 */
export interface ErrorContext {
  name: string;
  message: string;
  stack?: string;
  statusCode?: number;
}

/**
 * Comprehensive logging interceptor with correlation tracking
 */
@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  private readonly logger = new Logger(LoggingInterceptor.name);

  constructor(private readonly metricsService?: MetricsService) {
    this.logger.log(
      'Logging Interceptor initialized - Structured logging enabled',
    );
  }

  /**
   * Intercept HTTP requests and responses for comprehensive logging
   *
   * @param context Execution context
   * @param next Call handler
   * @returns Observable with logging side effects
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const httpContext = context.switchToHttp();
    const request = httpContext.getRequest<Request>();
    const response = httpContext.getResponse<Response>();

    // Generate correlation ID
    const correlationId = this.generateCorrelationId(request);

    // Add correlation ID to request headers for downstream services
    request.headers['x-correlation-id'] = correlationId;
    response.setHeader('X-Correlation-ID', correlationId);

    // Create request context
    const requestContext = this.createRequestContext(request, correlationId);

    const startTime = Date.now();
    const route = this.extractRoute(request);

    // Log request start
    this.logRequest(requestContext);

    // Track request start metrics
    if (this.metricsService) {
      this.metricsService.recordRequestStart(request.method, route);
    }

    return next.handle().pipe(
      tap(() => {
        // Handle successful response
        const processingTime = Date.now() - startTime;
        const responseContext = this.createResponseContext(
          response,
          processingTime,
        );

        this.logResponse(requestContext, responseContext);

        // Record metrics for successful requests
        if (this.metricsService) {
          this.metricsService.recordApiRequestDuration(
            request.method,
            route,
            response.statusCode,
            processingTime,
          );
          this.metricsService.recordRequestEnd(request.method, route);
        }
      }),
      catchError((_error: Error) => {
        // Handle error response
        const processingTime = Date.now() - startTime;
        const responseContext = this.createResponseContext(
          response,
          processingTime,
        );
        const errorContext = this.createErrorContext(_error);

        this.logError(requestContext, responseContext, errorContext);

        // Record metrics for failed requests
        if (this.metricsService) {
          const statusCode: number =
            Number(
              (_error as HttpErrorWithStatus)?.status ??
                (_error as HttpErrorWithStatus)?.statusCode,
            ) || 500;
          this.metricsService.recordApiRequestDuration(
            request.method,
            route,
            statusCode,
            processingTime,
          );
          this.metricsService.recordRequestEnd(request.method, route);
        }

        // Re-throw the error to maintain normal error handling using throwError
        return throwError(() => _error);
      }),
    );
  }

  /**
   * Generate or retrieve correlation ID from request
   *
   * @param request HTTP request object
   * @returns Correlation ID string
   */
  private generateCorrelationId(request: Request): string {
    // Check if correlation ID already exists (from upstream service)
    const existingId =
      request.headers['x-correlation-id'] ??
      request.headers['x-request-id'] ??
      request.headers['x-trace-id'];

    return (existingId as string) ?? _uuidv4();
  }

  /**
   * Create structured request context
   *
   * @param request HTTP request object
   * @param correlationId Request correlation ID
   * @returns Request context object
   */
  private createRequestContext(
    request: Request,
    correlationId: string,
  ): RequestContext {
    return {
      correlationId,
      method: request.method,
      url: request.originalUrl ?? request.url,
      userAgent: request.headers['user-agent'],
      remoteAddress: this.getClientIpAddress(request),
      timestamp: new Date().toISOString(),
      userId: (request as Request & { user?: { id: string } }).user?.id, // If authentication is implemented
      sessionId: (request as Request & { session?: { id: string } }).session
        ?.id, // If sessions are used
    };
  }

  /**
   * Create structured response context
   *
   * @param response HTTP response object
   * @param processingTime Request processing time in milliseconds
   * @returns Response context object
   */
  private createResponseContext(
    response: Response,
    processingTime: number,
  ): ResponseContext {
    return {
      statusCode: response.statusCode,
      processingTime,
      contentLength:
        parseInt(response.get('Content-Length') ?? '0', 10) ?? undefined,
      cacheHit: response.get('X-Cache-Status') === 'HIT',
    };
  }

  /**
   * Create structured error context
   *
   * @param error Error object
   * @returns Error context object
   */
  private createErrorContext(error: Error): ErrorContext {
    return {
      name: error?.name ?? 'UnknownError',
      message: error?.message ?? 'An unknown error occurred',
      stack: error?.stack,
      statusCode:
        'status' in error && typeof error.status === 'number'
          ? error.status
          : 'statusCode' in error && typeof error.statusCode === 'number'
            ? error.statusCode
            : undefined,
    };
  }

  /**
   * Extract route pattern from request
   *
   * @param request HTTP request object
   * @returns Route pattern string
   */
  private extractRoute(request: Request): string {
    // Try to get route pattern from NestJS route info
    const routePattern = (request as Request & { route?: { path: string } })
      .route?.path;
    if (routePattern && typeof routePattern === 'string') {
      return routePattern;
    }

    // Fallback to URL path with parameter normalization
    const url = request.originalUrl ?? request.url;
    return this.normalizeUrlForMetrics(url);
  }

  /**
   * Normalize URL path for consistent metrics grouping
   *
   * @param url Original URL
   * @returns Normalized URL pattern
   */
  private normalizeUrlForMetrics(url: string): string {
    // Remove query parameters
    const path = url.split('?')[0];

    // Replace common ID patterns with placeholders
    return (path ?? '')
      .replace(/\/\d+/g, '/:id') // Replace numeric IDs
      .replace(/\/[a-f0-9-]{36}/g, '/:uuid') // Replace UUIDs
      .replace(/\/[a-f0-9]{24}/g, '/:objectId') // Replace MongoDB ObjectIDs
      .replace(/\/$/, ''); // Remove trailing slash
  }

  /**
   * Get client IP address from request
   *
   * @param request HTTP request object
   * @returns Client IP address
   */
  private getClientIpAddress(request: Request): string {
    return (request.headers['x-forwarded-for'] ??
      request.headers['x-real-ip'] ??
      request.connection?.remoteAddress ??
      request.socket?.remoteAddress ??
      'unknown') as string;
  }

  /**
   * Log successful request
   *
   * @param requestContext Request context information
   */
  private logRequest(requestContext: RequestContext): void {
    this.logger.log({
      message: 'HTTP Request Started',
      level: 'info',
      type: 'http_request',
      context: requestContext,
      timestamp: requestContext.timestamp,
    });
  }

  /**
   * Log successful response
   *
   * @param requestContext Request context information
   * @param responseContext Response context information
   */
  private logResponse(
    requestContext: RequestContext,
    responseContext: ResponseContext,
  ): void {
    const logLevel = responseContext.statusCode >= 400 ? 'warn' : 'info';
    const message = `HTTP Request Completed - ${requestContext.method} ${requestContext.url} - ${responseContext.statusCode}`;

    const logData = {
      message,
      level: logLevel,
      type: 'http_response',
      context: {
        request: requestContext,
        response: responseContext,
      },
      timestamp: new Date().toISOString(),
    };

    if (logLevel === 'warn') {
      this.logger.warn(logData);
    } else {
      this.logger.log(logData);
    }
  }

  /**
   * Log error response
   *
   * @param requestContext Request context information
   * @param responseContext Response context information
   * @param errorContext Error context information
   */
  private logError(
    requestContext: RequestContext,
    responseContext: ResponseContext,
    errorContext: ErrorContext,
  ): void {
    this.logger.error({
      message: `HTTP Request Failed - ${requestContext.method} ${requestContext.url} - ${errorContext.name}`,
      level: 'error',
      type: 'http_error',
      context: {
        request: requestContext,
        response: responseContext,
        error: errorContext,
      },
      timestamp: new Date().toISOString(),
    });
  }
}

