// ===== ENTERPRISE API TYPES =====

/**
 * Enterprise API request wrapper with Parlant context
 */
export interface EnterpriseApiRequest {
  /** Target service and endpoint */
  target: {
    service: string;
    controller: string;
    method: string;
    path: string;
  };

  /** HTTP method and parameters */
  httpMethod: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  pathParams?: Record<string, string>;
  queryParams?: Record<string, unknown>;
  bodyParams?: unknown;
  headers?: Record<string, string>;

  /** Parlant validation context */
  conversationContext: {
    sessionId: string;
    userIntent?: string;
    conversationHistory?: Array<{
      timestamp: string;
      speaker: 'USER' | 'ASSISTANT' | 'SYSTEM';
      message: string;
    }>;
    apiUsageContext?: {
      applicationContext: string;
      businessPurpose: string;
      expectedOutcome: string;
      riskLevel: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
    };
  };

  /** Enterprise request options */
  enterpriseOptions?: {
    bypassCache?: boolean;
    enableMonitoring?: boolean;
    auditLevel?: 'BASIC' | 'DETAILED' | 'COMPREHENSIVE';
    timeoutMs?: number;
    retryPolicy?: {
      maxRetries: number;
      backoffStrategy: 'LINEAR' | 'EXPONENTIAL';
    };
  };
}

/**
 * Enterprise API response wrapper with validation and audit details
 */
export interface EnterpriseApiResponse<T = unknown> {
  /** Original API response data */
  data: T;

  /** Parlant validation details */
  validation: {
    approved: boolean;
    conversationId: string;
    validationTimestamp: Date;
    reasoning: string;
    confidence: number;
    riskAssessment: {
      level: string;
      factors: string[];
      mitigations: string[];
    };
  };

  /** Enterprise metadata */
  metadata: {
    operationId: string;
    apiVersion: string;
    processingTime: {
      validationMs: number;
      executionMs: number;
      totalMs: number;
    };
    performance: {
      cacheHit: boolean;
      circuitBreakerState: string;
      resourceUsage: {
        cpu: number;
        memory: number;
        network: number;
      };
    };
    compliance: {
      auditTrailId: string;
      regulatoryFlags: string[];
      retentionPolicy: string;
    };
  };

  /** Quality and reliability metrics */
  quality: {
    successRate: number;
    errorRate: number;
    performanceScore: number;
    reliabilityScore: number;
  };
}

/**
 * Enterprise API analytics and monitoring
 */
export interface EnterpriseApiAnalytics {
  /** Overall system metrics */
  system: {
    totalRequests: number;
    successRate: number;
    averageResponseTime: number;
    errorRate: number;
    uptime: number;
  };

  /** Service-specific metrics */
  services: Record<string, {
    requestCount: number;
    successRate: number;
    averageResponseTime: number;
    errorTypes: Record<string, number>;
    performanceTrend: Array<{
      timestamp: Date;
      responseTime: number;
      successRate: number;
    }>;
  }>;

  /** Parlant validation metrics */
  validation: {
    totalValidations: number;
    approvalRate: number;
    averageValidationTime: number;
    riskDistribution: Record<string, number>;
    topDenialReasons: Array<{
      reason: string;
      count: number;
      percentage: number;
    }>;
  };

  /** Enterprise compliance metrics */
  compliance: {
    auditTrailCoverage: number;
    complianceViolations: number;
    dataRetentionCompliance: number;
    securityEventCount: number;
  };
}

/**
 * Circuit breaker configuration for API resilience
 */
interface CircuitBreakerConfig {
  failureThreshold: number;
  timeoutMs: number;
  resetTimeoutMs: number;
  monitoringEnabled: boolean;
}

/**
 * API endpoint configuration for enterprise features
 */
interface ApiEndpointConfig {
  endpoint: string;
  service: string;
  requiresValidation: boolean;
  riskLevel: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  cacheStrategy: 'NONE' | 'SHORT' | 'MEDIUM' | 'LONG';
  circuitBreaker: CircuitBreakerConfig;
  complianceLevel: 'BASIC' | 'STANDARD' | 'HIGH' | 'MAXIMUM';
}

