    const validationRequest: ParlantValidationRequest = {
      functionName: `RoutingService.HealthUpdate.${serviceId}`,
      functionParams: {
        serviceId,
        health,
        responseTime: healthData.responseTime,
        errorRate: healthData.errorRate,
