    } catch (_error) {
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown error';
      this.logger.error(`[${operationId}] Detailed status check failed: ${errorMessage}`, {
        operationId,
        userId: user.id,
        error: errorMessage,
      });

      return {
        status: 'error',
        timestamp: new Date().toISOString(),
        error: errorMessage,
        services: {},
      };
    }
  }
}

