  Base64ImageCompressor,
  compressPngBase64Under1MB,
  CompressionOptions as _CompressionOptions,
  CompressionResult as _CompressionResult,
} from '../compressor';

/**
 * Test utilities for index module testing
 */
class IndexTestUtils {
  /**
   * Validate that an export exists and has correct type
   */
  static validateExport(
    exportObj: any,
    name: string,
    expectedType: string,
    expectedConstructor?: any,
  ): void {
    expect(exportObj).toBeDefined();
    expect(typeof exportObj).toBe(expectedType);

    if (expectedConstructor && expectedType === 'function') {
      expect(exportObj).toBe(expectedConstructor);
    }
  }

  /**
   * Check if an object is a constructor function
   */
  static isConstructor(obj: unknown): boolean {
    return (typeof obj === 'function' &&
      obj.prototype &&
      obj.prototype.constructor === obj) as boolean;
  }

  /**
   * Get all property names including non-enumerable ones
   */
  static getAllPropertyNames(obj: unknown): string[] {
    const props: string[] = [];
    let current = obj as object | null;

    do {
      Object.getOwnPropertyNames(current).forEach((_name) => {
        if (!props.includes(_name)) {
          props.push(_name);
        }
      });
      current = Object.getPrototypeOf(current) as object | null;
    } while (current && current !== Object.prototype);

    return props.sort();
  }

  /**
   * Calculate approximate memory footprint of an object
   */
  static getApproximateSize(obj: unknown): number {
    const visited = new WeakSet();

    function calculateSize(value: unknown): number {
      if (value === null || typeof value !== 'object') {
        return 8; // Approximate size for primitives
      }

      if (visited.has(value)) {
        return 0; // Already counted
      }

      visited.add(value);

      let size = 0;
      for (const key in value) {
        if (Object.prototype.hasOwnProperty.call(value, key)) {
          size += key.length * 2; // String key size
          size += calculateSize((value as Record<string, unknown>)[key]);
        }
      }

      return size;
    }

    return calculateSize(obj);
  }
}

