  readonly regulation: 'GDPR' | 'SOX' | 'HIPAA' | 'ISO27001' | 'PCI_DSS';
  readonly requirement: string;
  readonly status: 'COMPLIANT' | 'NON_COMPLIANT' | 'REQUIRES_REVIEW';
