  readonly priority: 'critical' | 'high' | 'medium' | 'low';
  readonly issue: string;
  readonly recommendation: string;
  readonly expectedImprovement: string;
  readonly implementationComplexity: 'low' | 'medium' | 'high';
}

// ===== PERFORMANCE MONITOR SERVICE =====

@Injectable()
export class ParlantPerformanceMonitorService {
  private readonly logger = new Logger(ParlantPerformanceMonitorService.name);
  private readonly metrics: ParlantPerformanceMetrics[] = [];
  private readonly performanceAlerts: PerformanceAlertConfig;

  // Real-time tracking
  private activeOperations = new Map<string, { startTime: number; functionName: string }>();
  private currentThroughput = 0;
  private lastThroughputUpdate = Date.now();

  // Performance optimization
  private performanceOptimizationEnabled = true;
  private metricsRetentionDays = 7;
  private maxMetricsInMemory = 10000;

  constructor(private readonly configService: ConfigService) {
    const operationId = `perf_monitor_init_${Date.now()}_${Math.random().toString(36).substring(7)}`;

    this.performanceAlerts = {
      enabled: this.configService.get<boolean>('PARLANT_PERFORMANCE_ALERTS_ENABLED', true),
      thresholds: {
        maxAverageLatency: this.configService.get<number>('PARLANT_MAX_AVG_LATENCY_MS', 500),
        maxP95Latency: this.configService.get<number>('PARLANT_MAX_P95_LATENCY_MS', 1000),
        minThroughputRpm: this.configService.get<number>('PARLANT_MIN_THROUGHPUT_RPM', 25),
        minCacheHitRate: this.configService.get<number>('PARLANT_MIN_CACHE_HIT_RATE', 95),
        maxErrorRate: this.configService.get<number>('PARLANT_MAX_ERROR_RATE', 5),
      },
      alertActions: ['log', 'webhook'],
    };

    this.logger.log(`[${operationId}] Initializing Parlant Performance Monitor`, {
      alertsEnabled: this.performanceAlerts.enabled,
      thresholds: this.performanceAlerts.thresholds,
      optimizationEnabled: this.performanceOptimizationEnabled,
      retentionDays: this.metricsRetentionDays,
    });

    // Start periodic monitoring and cleanup
    this.startPeriodicMonitoring();
  }

  /**
   * Start performance tracking for a Parlant operation
   * 
   * @param operationId - Unique identifier for the operation
   * @param functionName - Name of the function being validated
   * @returns Performance tracking context
   */
  startPerformanceTracking(operationId: string, functionName: string): void {
    const startTime = performance.now();

    this.activeOperations.set(operationId, {
      startTime,
      functionName,
    });

    this.logger.debug(`[${operationId}] Performance tracking started for ${functionName}`, {
      operationId,
      functionName,
      startTime,
      activeOperations: this.activeOperations.size,
    });
  }

  /**
   * Complete performance tracking and record metrics
   * 
   * @param operationId - Operation identifier
   * @param validationType - Type of validation performed
   * @param cacheHit - Whether operation used cache
   * @param errorOccurred - Whether an error occurred
   */
  completePerformanceTracking(
    operationId: string,
    validationType: ParlantPerformanceMetrics['validationType'],
    cacheHit: boolean,
    errorOccurred: boolean = false
  ): ParlantPerformanceMetrics | null {
    const endTime = performance.now();
    const operation = this.activeOperations.get(operationId);

    if (!operation) {
      this.logger.warn(`[${operationId}] No active operation found for performance tracking`);
      return null;
    }

    const duration = endTime - operation.startTime;
    const memoryUsage = process.memoryUsage();

    // Update throughput calculations
    this.updateThroughputMetrics();

    const metrics: ParlantPerformanceMetrics = {
      operationId,
      functionName: operation.functionName,
      startTime: operation.startTime,
      endTime,
      duration,
      validationType,
      cacheHit,
      errorOccurred,
      throughputRpm: this.currentThroughput,
      memoryUsage,
      timestamp: new Date(),
    };

    // Store metrics
    this.storeMetrics(metrics);

    // Clean up active operation
    this.activeOperations.delete(operationId);

    // Check performance thresholds and generate alerts if needed
    this.checkPerformanceThresholds(metrics);

    this.logger.debug(`[${operationId}] Performance tracking completed`, {
      operationId,
      functionName: operation.functionName,
      duration: `${duration.toFixed(2)}ms`,
      validationType,
      cacheHit,
      errorOccurred,
      throughputRpm: this.currentThroughput,
    });

    return metrics;
  }

  /**
   * Get current performance statistics
   * 
   * @param period - Time period for statistics
   * @returns Aggregated performance statistics
   */
  getPerformanceStats(period: ParlantPerformanceStats['period'] = 'hour'): ParlantPerformanceStats {
    const periodMs = this.getPeriodInMs(period);
    const cutoffTime = Date.now() - periodMs;

    const recentMetrics = this.metrics.filter(
      metric => metric.timestamp.getTime() > cutoffTime
    );

    if (recentMetrics.length === 0) {
      return this.getEmptyStats(period);
    }

    // Calculate latency statistics
    const latencies = recentMetrics.map(m => m.duration).sort((a, b) => a - b);
    const averageLatency = latencies.reduce((sum, lat) => sum + lat, 0) / latencies.length;
    const medianLatency = latencies[Math.floor(latencies.length / 2)];
    const p95Index = Math.floor(latencies.length * 0.95);
    const p99Index = Math.floor(latencies.length * 0.99);

    // Calculate rates
    const cacheHits = recentMetrics.filter(m => m.cacheHit).length;
    const errors = recentMetrics.filter(m => m.errorOccurred).length;
    const cacheHitRate = (cacheHits / recentMetrics.length) * 100;
    const errorRate = (errors / recentMetrics.length) * 100;

    // Calculate throughput
    const throughputRpm = (recentMetrics.length / (periodMs / 1000)) * 60;

    // Performance score (0-100)
    const performanceScore = this.calculatePerformanceScore({
      averageLatency,
      p95Latency: latencies[p95Index] || 0,
      throughputRpm,
      cacheHitRate,
      errorRate,
    });

    // Check if targets are met
    const targetsMet = {
      avgUnder500ms: averageLatency < this.performanceAlerts.thresholds.maxAverageLatency,
      p95Under1000ms: (latencies[p95Index] || 0) < this.performanceAlerts.thresholds.maxP95Latency,
      throughputOver25: throughputRpm > this.performanceAlerts.thresholds.minThroughputRpm,
      cacheHitOver95: cacheHitRate > this.performanceAlerts.thresholds.minCacheHitRate,
    };

    return {
      period,
      totalOperations: recentMetrics.length,
      averageLatency,
      medianLatency,
      p95Latency: latencies[p95Index] || 0,
      p99Latency: latencies[p99Index] || 0,
      maxLatency: Math.max(...latencies),
      minLatency: Math.min(...latencies),
      throughputRpm,
      cacheHitRate,
      errorRate,
      performanceScore,
      targetsMet,
    };
  }

  /**
   * Generate performance optimization recommendations
   * 
   * @returns Array of optimization recommendations
   */
  generatePerformanceRecommendations(): PerformanceRecommendation[] {
    const stats = this.getPerformanceStats('hour');
    const recommendations: PerformanceRecommendation[] = [];

    // Latency recommendations
    if (!stats.targetsMet.avgUnder500ms) {
      recommendations.push({
        category: 'caching',
        priority: 'critical',
        issue: `Average latency ${stats.averageLatency.toFixed(2)}ms exceeds 500ms target`,
        recommendation: 'Implement intelligent caching with longer TTL for low-risk operations',
        expectedImprovement: '40-60% latency reduction',
        implementationComplexity: 'medium',
      });
    }

    if (!stats.targetsMet.p95Under1000ms) {
      recommendations.push({
        category: 'concurrency',
        priority: 'high',
        issue: `95th percentile latency ${stats.p95Latency.toFixed(2)}ms exceeds 1000ms target`,
        recommendation: 'Implement circuit breaker pattern and async validation queuing',
        expectedImprovement: '30-50% p95 latency reduction',
        implementationComplexity: 'high',
      });
    }

    // Cache hit rate recommendations
    if (!stats.targetsMet.cacheHitOver95) {
      recommendations.push({
        category: 'caching',
        priority: 'high',
        issue: `Cache hit rate ${stats.cacheHitRate.toFixed(1)}% below 95% target`,
        recommendation: 'Implement Redis cluster with intelligent cache warming',
        expectedImprovement: '15-25% cache hit rate improvement',
        implementationComplexity: 'medium',
      });
    }

    // Throughput recommendations
    if (!stats.targetsMet.throughputOver25) {
      recommendations.push({
        category: 'concurrency',
        priority: 'medium',
        issue: `Throughput ${stats.throughputRpm.toFixed(1)} RPM below 25 RPM target`,
        recommendation: 'Implement connection pooling and batch validation processing',
        expectedImprovement: '100-200% throughput increase',
        implementationComplexity: 'medium',
      });
    }

    // Memory optimization
    const memoryUsage = process.memoryUsage();
    if (memoryUsage.heapUsed > 100 * 1024 * 1024) { // 100MB
      recommendations.push({
        category: 'memory',
        priority: 'medium',
        issue: `High memory usage: ${Math.round(memoryUsage.heapUsed / 1024 / 1024)}MB`,
        recommendation: 'Implement metrics cleanup and cache size limits',
        expectedImprovement: '30-50% memory usage reduction',
        implementationComplexity: 'low',
      });
    }

    return recommendations;
  }

  /**
   * Get real-time performance dashboard data
   * 
   * @returns Dashboard data for monitoring interfaces
   */
  getPerformanceDashboardData(): {
    currentStats: ParlantPerformanceStats;
    recentMetrics: ParlantPerformanceMetrics[];
    activeOperations: number;
    recommendations: PerformanceRecommendation[];
    alerts: string[];
  } {
    return {
      currentStats: this.getPerformanceStats('hour'),
      recentMetrics: this.metrics.slice(-100), // Last 100 operations
      activeOperations: this.activeOperations.size,
      recommendations: this.generatePerformanceRecommendations(),
      alerts: this.getActiveAlerts(),
    };
  }

  // ===== PRIVATE HELPER METHODS =====

  private storeMetrics(metrics: ParlantPerformanceMetrics): void {
    this.metrics.push(metrics);

    // Cleanup old metrics to prevent memory leaks
    if (this.metrics.length > this.maxMetricsInMemory) {
      const removeCount = this.metrics.length - this.maxMetricsInMemory;
      this.metrics.splice(0, removeCount);
    }

    // TODO: Persist to database for long-term storage
    // await this.persistMetrics(metrics);
  }

  private updateThroughputMetrics(): void {
    const now = Date.now();
    const timeSinceLastUpdate = now - this.lastThroughputUpdate;

    if (timeSinceLastUpdate > 60000) { // Update every minute
      const recentMetrics = this.metrics.filter(
        m => m.timestamp.getTime() > now - 60000
      );
      this.currentThroughput = recentMetrics.length;
      this.lastThroughputUpdate = now;
    }
  }

  private checkPerformanceThresholds(metrics: ParlantPerformanceMetrics): void {
    if (!this.performanceAlerts.enabled) return;

    const alerts: string[] = [];

    // Check individual operation latency
    if (metrics.duration > this.performanceAlerts.thresholds.maxAverageLatency * 2) {
      alerts.push(`High latency operation: ${metrics.duration.toFixed(2)}ms for ${metrics.functionName}`);
    }

    // Check error occurrence
    if (metrics.errorOccurred) {
      alerts.push(`Error in operation: ${metrics.operationId} (${metrics.functionName})`);
    }

    // Send alerts if any triggered
    if (alerts.length > 0) {
      this.sendPerformanceAlerts(alerts);
    }
  }

  private sendPerformanceAlerts(alerts: string[]): void {
    alerts.forEach(alert => {
      this.logger.warn(`Performance Alert: ${alert}`);

      // TODO: Implement additional alert actions (email, webhook)
      // if (this.performanceAlerts.alertActions.includes('email')) {
      //   await this.sendEmailAlert(alert);
      // }
      // if (this.performanceAlerts.alertActions.includes('webhook')) {
      //   await this.sendWebhookAlert(alert);
      // }
    });
  }

  private getActiveAlerts(): string[] {
    const stats = this.getPerformanceStats('hour');
    const alerts: string[] = [];

    if (!stats.targetsMet.avgUnder500ms) {
      alerts.push(`Average latency ${stats.averageLatency.toFixed(2)}ms exceeds 500ms target`);
    }

    if (!stats.targetsMet.p95Under1000ms) {
      alerts.push(`95th percentile latency ${stats.p95Latency.toFixed(2)}ms exceeds 1000ms target`);
    }

    if (!stats.targetsMet.cacheHitOver95) {
      alerts.push(`Cache hit rate ${stats.cacheHitRate.toFixed(1)}% below 95% target`);
    }

    if (!stats.targetsMet.throughputOver25) {
      alerts.push(`Throughput ${stats.throughputRpm.toFixed(1)} RPM below 25 RPM target`);
    }

    return alerts;
  }

  private calculatePerformanceScore(metrics: {
    averageLatency: number;
    p95Latency: number;
    throughputRpm: number;
    cacheHitRate: number;
    errorRate: number;
  }): number {
    let score = 100;

    // Latency scoring (40% of total score)
    const latencyScore = Math.max(0, 100 - (metrics.averageLatency / 500) * 40);
    const p95Score = Math.max(0, 100 - (metrics.p95Latency / 1000) * 40);

    // Throughput scoring (20% of total score)
    const throughputScore = Math.min(100, (metrics.throughputRpm / 25) * 20);

    // Cache hit rate scoring (20% of total score)
    const cacheScore = (metrics.cacheHitRate / 100) * 20;

    // Error rate scoring (20% of total score)
    const errorScore = Math.max(0, 20 - (metrics.errorRate / 5) * 20);

    score = (latencyScore * 0.2) + (p95Score * 0.2) + throughputScore + cacheScore + errorScore;

    return Math.max(0, Math.min(100, score));
  }

  private getPeriodInMs(period: ParlantPerformanceStats['period']): number {
    switch (period) {
      case 'minute': return 60 * 1000;
      case 'hour': return 60 * 60 * 1000;
      case 'day': return 24 * 60 * 60 * 1000;
      default: return 60 * 60 * 1000;
    }
  }

  private getEmptyStats(period: ParlantPerformanceStats['period']): ParlantPerformanceStats {
    return {
      period,
      totalOperations: 0,
      averageLatency: 0,
      medianLatency: 0,
      p95Latency: 0,
      p99Latency: 0,
      maxLatency: 0,
      minLatency: 0,
      throughputRpm: 0,
      cacheHitRate: 0,
      errorRate: 0,
      performanceScore: 0,
      targetsMet: {
        avgUnder500ms: true,
        p95Under1000ms: true,
        throughputOver25: false,
        cacheHitOver95: false,
      },
    };
  }

  private startPeriodicMonitoring(): void {
    // Performance metrics logging every 5 minutes
    setInterval(() => {
      const stats = this.getPerformanceStats('hour');
      this.logger.log('Parlant Performance Metrics Summary', {
        totalOperations: stats.totalOperations,
        averageLatency: `${stats.averageLatency.toFixed(2)}ms`,
        p95Latency: `${stats.p95Latency.toFixed(2)}ms`,
        throughputRpm: `${stats.throughputRpm.toFixed(1)} RPM`,
        cacheHitRate: `${stats.cacheHitRate.toFixed(1)}%`,
        performanceScore: `${stats.performanceScore.toFixed(1)}/100`,
        targetsMet: stats.targetsMet,
      });
    }, 5 * 60 * 1000);

    // Cleanup old metrics daily
    setInterval(() => {
      const cutoffTime = Date.now() - (this.metricsRetentionDays * 24 * 60 * 60 * 1000);
      const initialLength = this.metrics.length;

      this.metrics.splice(0, this.metrics.findIndex(m => m.timestamp.getTime() > cutoffTime));

      if (this.metrics.length !== initialLength) {
        this.logger.log(`Cleaned up ${initialLength - this.metrics.length} old performance metrics`);
      }
    }, 24 * 60 * 60 * 1000);
  }
}

/**
 * Parlant Circuit Breaker Service - Enterprise Resilience & Connection Management
 * 
 * Provides circuit breaker pattern implementation and connection pooling for Parlant
 * API calls ensuring 99%+ availability and automatic failover capabilities.
 * 
 * Features:
 * - Circuit breaker pattern with configurable thresholds
 * - Connection pooling for Parlant API with intelligent load balancing
 * - Automatic failover and retry strategies
 * - Rate limiting and backpressure management
 * - Health monitoring and endpoint availability tracking
 * - Enterprise-grade resilience patterns
 * 
 * Architecture: Multi-tier resilience with intelligent fallback
 * Availability: 99%+ uptime target with automatic failover
 * Performance: Sub-100ms circuit breaker decisions
 */

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { EventEmitter } from 'events';

// ===== CIRCUIT BREAKER INTERFACES =====

/**
 * Circuit breaker state types
 */
export enum CircuitBreakerState {
  CLOSED = 'CLOSED',     // Normal operation
  OPEN = 'OPEN',         // Failing fast
  HALF_OPEN = 'HALF_OPEN' // Testing recovery
}

/**
 * Circuit breaker configuration
 */
export interface CircuitBreakerConfig {
  readonly failureThreshold: number;      // Number of failures to open circuit
  readonly recoveryTimeout: number;       // Time before attempting recovery (ms)
  readonly successThreshold: number;      // Successes needed to close circuit
  readonly timeWindow: number;            // Time window for failure counting (ms)
  readonly minimumRequests: number;       // Minimum requests before evaluation
  readonly enabled: boolean;
}

/**
 * Connection pool configuration
 */
export interface ConnectionPoolConfig {
  readonly maxConnections: number;        // Maximum concurrent connections
  readonly minConnections: number;        // Minimum idle connections
  readonly acquireTimeoutMs: number;      // Max time to acquire connection
  readonly idleTimeoutMs: number;         // Max idle time before cleanup
  readonly retryAttempts: number;         // Connection retry attempts
  readonly healthCheckIntervalMs: number; // Health check frequency
}

/**
 * Circuit breaker statistics
 */
export interface CircuitBreakerStats {
  readonly state: CircuitBreakerState;
  readonly totalRequests: number;
  readonly successCount: number;
  readonly failureCount: number;
  readonly lastFailureTime: Date | null;
  readonly lastSuccessTime: Date | null;
  readonly stateChangedAt: Date;
  readonly consecutiveFailures: number;
  readonly consecutiveSuccesses: number;
  readonly failureRate: number;
  readonly averageResponseTime: number;
}

/**
 * Connection pool statistics
 */
export interface ConnectionPoolStats {
  readonly totalConnections: number;
  readonly activeConnections: number;
  readonly idleConnections: number;
  readonly pendingRequests: number;
  readonly totalAcquired: number;
  readonly totalReleased: number;
  readonly averageAcquireTime: number;
  readonly healthyEndpoints: number;
  readonly unhealthyEndpoints: number;
}

/**
 * API endpoint health status
 */
export interface EndpointHealth {
  readonly url: string;
  readonly healthy: boolean;
  readonly lastCheck: Date;
  readonly responseTime: number;
  readonly consecutiveFailures: number;
  readonly lastError?: string;
}

/**
 * Resilience operation result
 */
export interface ResilienceResult<T> {
  readonly success: boolean;
  readonly data?: T;
  readonly error?: Error;
  readonly fromCache: boolean;
  readonly retryAttempt: number;
  readonly responseTime: number;
  readonly endpoint?: string;
}

// ===== CIRCUIT BREAKER SERVICE =====

@Injectable()
export class ParlantCircuitBreakerService extends EventEmitter {
  private readonly logger = new Logger(ParlantCircuitBreakerService.name);

  // Circuit breaker state
  private state: CircuitBreakerState = CircuitBreakerState.CLOSED;
  private consecutiveFailures = 0;
  private consecutiveSuccesses = 0;
  private lastFailureTime: Date | null = null;
  private lastSuccessTime: Date | null = null;
  private stateChangedAt = new Date();

  // Request tracking
  private requestWindow: { timestamp: number; success: boolean; responseTime: number }[] = [];
  private totalRequests = 0;
  private successCount = 0;
  private failureCount = 0;

  // Connection pool
  private readonly connectionPool: Map<string, any> = new Map();
  private readonly activeConnections = new Set<string>();
  private readonly pendingRequests: Array<{
    resolve: (connection: any) => void;
    reject: (error: Error) => void;
    timestamp: number;
  }> = [];

  // Endpoint health tracking
  private readonly endpointHealth: Map<string, EndpointHealth> = new Map();
  private readonly parlantEndpoints: string[];

  // Configuration
  private readonly circuitConfig: CircuitBreakerConfig;
  private readonly poolConfig: ConnectionPoolConfig;

  constructor(private readonly configService: ConfigService) {
    super();

    this.circuitConfig = {
      failureThreshold: this.configService.get<number>('PARLANT_CIRCUIT_FAILURE_THRESHOLD', 5),
      recoveryTimeout: this.configService.get<number>('PARLANT_CIRCUIT_RECOVERY_TIMEOUT_MS', 60000),
      successThreshold: this.configService.get<number>('PARLANT_CIRCUIT_SUCCESS_THRESHOLD', 3),
      timeWindow: this.configService.get<number>('PARLANT_CIRCUIT_TIME_WINDOW_MS', 60000),
      minimumRequests: this.configService.get<number>('PARLANT_CIRCUIT_MIN_REQUESTS', 10),
      enabled: this.configService.get<boolean>('PARLANT_CIRCUIT_BREAKER_ENABLED', true),
    };

    this.poolConfig = {
      maxConnections: this.configService.get<number>('PARLANT_POOL_MAX_CONNECTIONS', 20),
      minConnections: this.configService.get<number>('PARLANT_POOL_MIN_CONNECTIONS', 5),
      acquireTimeoutMs: this.configService.get<number>('PARLANT_POOL_ACQUIRE_TIMEOUT_MS', 5000),
      idleTimeoutMs: this.configService.get<number>('PARLANT_POOL_IDLE_TIMEOUT_MS', 300000),
      retryAttempts: this.configService.get<number>('PARLANT_POOL_RETRY_ATTEMPTS', 3),
      healthCheckIntervalMs: this.configService.get<number>('PARLANT_POOL_HEALTH_CHECK_MS', 30000),
    };

    this.parlantEndpoints = this.configService.get<string[]>('PARLANT_API_ENDPOINTS', [
      'http://localhost:8000',
    ]);

    const operationId = `circuit_breaker_init_${Date.now()}_${Math.random().toString(36).substring(7)}`;

    this.logger.log(`[${operationId}] Initializing Parlant Circuit Breaker Service`, {
      circuitConfig: this.circuitConfig,
      poolConfig: this.poolConfig,
      endpoints: this.parlantEndpoints,
      initialState: this.state,
    });

    // Initialize connection pool and health monitoring
    this.initializeConnectionPool();
    this.startHealthMonitoring();
    this.startPoolMaintenance();
  }

  /**
   * Execute operation with circuit breaker protection
   * 
   * @param operation - Function to execute with protection
   * @param operationId - Unique operation identifier
   * @returns Result with resilience metadata
   */
  async executeWithProtection<T>(
    operation: () => Promise<T>,
    operationId: string
  ): Promise<ResilienceResult<T>> {
    const startTime = performance.now();

    // Check circuit breaker state
    if (!this.canExecute()) {
      return {
        success: false,
        error: new Error(`Circuit breaker is ${this.state} - operation blocked`),
        fromCache: false,
        retryAttempt: 0,
        responseTime: performance.now() - startTime,
      };
    }

    try {
      // Execute operation with timeout
      const data = await this.executeWithTimeout(operation, operationId);
      const responseTime = performance.now() - startTime;

      // Record success
      this.recordSuccess(responseTime);

      this.logger.debug(`[${operationId}] Circuit breaker operation succeeded`, {
        operationId,
        responseTime: `${responseTime.toFixed(2)}ms`,
        state: this.state,
        consecutiveSuccesses: this.consecutiveSuccesses,
      });

      return {
        success: true,
        data,
        fromCache: false,
        retryAttempt: 0,
        responseTime,
      };

    } catch (error) {
      const responseTime = performance.now() - startTime;

      // Record failure
      this.recordFailure(error as Error, responseTime);

      this.logger.error(`[${operationId}] Circuit breaker operation failed`, {
        operationId,
        error: error instanceof Error ? error.message : String(error),
        responseTime: `${responseTime.toFixed(2)}ms`,
        state: this.state,
        consecutiveFailures: this.consecutiveFailures,
      });

      return {
        success: false,
        error: error as Error,
        fromCache: false,
        retryAttempt: 0,
        responseTime,
      };
    }
  }

  /**
   * Acquire connection from pool with circuit breaker protection
   * 
   * @param operationId - Operation identifier
   * @returns Connection or throws error
   */
  async acquireConnection(operationId: string): Promise<any> {
    const startTime = performance.now();

    if (!this.canExecute()) {
      throw new Error(`Circuit breaker is ${this.state} - connection acquisition blocked`);
    }

    return new Promise((resolve, reject) => {
      // Check for available connections
      const availableConnection = this.findAvailableConnection();
      if (availableConnection) {
        this.activeConnections.add(availableConnection.id);
        const acquireTime = performance.now() - startTime;

        this.logger.debug(`[${operationId}] Connection acquired from pool`, {
          operationId,
          connectionId: availableConnection.id,
          acquireTime: `${acquireTime.toFixed(2)}ms`,
          activeConnections: this.activeConnections.size,
        });

        resolve(availableConnection);
        return;
      }

      // Add to pending queue if pool is full
      if (this.activeConnections.size >= this.poolConfig.maxConnections) {
        this.pendingRequests.push({
          resolve,
          reject,
          timestamp: Date.now(),
        });

        // Set timeout for pending request
        setTimeout(() => {
          const index = this.pendingRequests.findIndex(req => req.resolve === resolve);
          if (index !== -1) {
            this.pendingRequests.splice(index, 1);
            reject(new Error('Connection acquisition timeout'));
          }
        }, this.poolConfig.acquireTimeoutMs);

        return;
      }

      // Create new connection
      this.createConnection()
        .then(connection => {
          this.activeConnections.add(connection.id);
          const acquireTime = performance.now() - startTime;

          this.logger.debug(`[${operationId}] New connection created`, {
            operationId,
            connectionId: connection.id,
            acquireTime: `${acquireTime.toFixed(2)}ms`,
            totalConnections: this.connectionPool.size,
          });

          resolve(connection);
        })
        .catch(error => {
          this.logger.error(`[${operationId}] Failed to create connection:`, error);
          reject(error);
        });
    });
  }

  /**
   * Release connection back to pool
   * 
   * @param connection - Connection to release
   * @param operationId - Operation identifier
   */
  async releaseConnection(connection: any, operationId: string): Promise<void> {
    if (!connection?.id) {
      this.logger.warn(`[${operationId}] Invalid connection for release`);
      return;
    }

    this.activeConnections.delete(connection.id);

    // Process pending requests
    if (this.pendingRequests.length > 0) {
      const pendingRequest = this.pendingRequests.shift();
      if (pendingRequest) {
        this.activeConnections.add(connection.id);
        pendingRequest.resolve(connection);

        this.logger.debug(`[${operationId}] Connection reassigned to pending request`, {
          operationId,
          connectionId: connection.id,
          pendingRequests: this.pendingRequests.length,
        });

        return;
      }
    }

    this.logger.debug(`[${operationId}] Connection released to pool`, {
      operationId,
      connectionId: connection.id,
      activeConnections: this.activeConnections.size,
      idleConnections: this.connectionPool.size - this.activeConnections.size,
    });
  }

  /**
   * Get circuit breaker statistics
   * 
   * @returns Current circuit breaker statistics
   */
  getCircuitBreakerStats(): CircuitBreakerStats {
    const recentRequests = this.getRecentRequests();
    const failureRate = recentRequests.length > 0 
      ? (recentRequests.filter(r => !r.success).length / recentRequests.length) * 100 
      : 0;

    const averageResponseTime = recentRequests.length > 0
      ? recentRequests.reduce((sum, r) => sum + r.responseTime, 0) / recentRequests.length
      : 0;

    return {
      state: this.state,
      totalRequests: this.totalRequests,
      successCount: this.successCount,
      failureCount: this.failureCount,
      lastFailureTime: this.lastFailureTime,
      lastSuccessTime: this.lastSuccessTime,
      stateChangedAt: this.stateChangedAt,
      consecutiveFailures: this.consecutiveFailures,
      consecutiveSuccesses: this.consecutiveSuccesses,
      failureRate,
      averageResponseTime,
    };
  }

  /**
   * Get connection pool statistics
   * 
   * @returns Current connection pool statistics
   */
  getConnectionPoolStats(): ConnectionPoolStats {
    return {
      totalConnections: this.connectionPool.size,
      activeConnections: this.activeConnections.size,
      idleConnections: this.connectionPool.size - this.activeConnections.size,
      pendingRequests: this.pendingRequests.length,
      totalAcquired: this.successCount, // Approximation
      totalReleased: this.successCount, // Approximation
      averageAcquireTime: 0, // TODO: Implement actual tracking
      healthyEndpoints: Array.from(this.endpointHealth.values()).filter(h => h.healthy).length,
      unhealthyEndpoints: Array.from(this.endpointHealth.values()).filter(h => !h.healthy).length,
    };
  }

  /**
   * Get endpoint health status
   * 
   * @returns Map of endpoint health statuses
   */
  getEndpointHealth(): Map<string, EndpointHealth> {
    return new Map(this.endpointHealth);
  }

  /**
   * Force circuit breaker state change (for testing/admin)
   * 
   * @param newState - New circuit breaker state
   * @param reason - Reason for state change
   */
  forceStateChange(newState: CircuitBreakerState, reason: string): void {
    const previousState = this.state;
    this.setState(newState);

    this.logger.warn(`Circuit breaker state forced from ${previousState} to ${newState}`, {
      reason,
      previousState,
      newState,
      timestamp: new Date().toISOString(),
    });

    this.emit('stateChanged', {
      previousState,
      newState,
      reason: `FORCED: ${reason}`,
      timestamp: new Date(),
    });
  }

  // ===== PRIVATE HELPER METHODS =====

  private canExecute(): boolean {
    if (!this.circuitConfig.enabled) return true;

    switch (this.state) {
      case CircuitBreakerState.CLOSED:
        return true;
      case CircuitBreakerState.OPEN:
        return this.shouldAttemptReset();
      case CircuitBreakerState.HALF_OPEN:
        return true;
      default:
        return false;
    }
  }

  private shouldAttemptReset(): boolean {
    if (!this.lastFailureTime) return false;
    return Date.now() - this.lastFailureTime.getTime() >= this.circuitConfig.recoveryTimeout;
  }

  private async executeWithTimeout<T>(
    operation: () => Promise<T>,
    operationId: string
  ): Promise<T> {
    const timeoutMs = 30000; // 30 second timeout

    return Promise.race([
      operation(),
      new Promise<never>((_, reject) => 
        setTimeout(() => reject(new Error('Operation timeout')), timeoutMs)
      ),
    ]);
  }

  private recordSuccess(responseTime: number): void {
    this.totalRequests++;
    this.successCount++;
    this.consecutiveSuccesses++;
    this.consecutiveFailures = 0;
    this.lastSuccessTime = new Date();

    this.requestWindow.push({
      timestamp: Date.now(),
      success: true,
      responseTime,
    });

    this.cleanupRequestWindow();

    // State transitions
    if (this.state === CircuitBreakerState.HALF_OPEN) {
      if (this.consecutiveSuccesses >= this.circuitConfig.successThreshold) {
        this.setState(CircuitBreakerState.CLOSED);
      }
    }
  }

  private recordFailure(error: Error, responseTime: number): void {
    this.totalRequests++;
    this.failureCount++;
    this.consecutiveFailures++;
    this.consecutiveSuccesses = 0;
    this.lastFailureTime = new Date();

    this.requestWindow.push({
      timestamp: Date.now(),
      success: false,
      responseTime,
    });

    this.cleanupRequestWindow();
    this.evaluateCircuitState();
  }

  private evaluateCircuitState(): void {
    if (!this.circuitConfig.enabled) return;

    const recentRequests = this.getRecentRequests();

    if (recentRequests.length < this.circuitConfig.minimumRequests) {
      return; // Not enough data to make decision
    }

    if (this.state === CircuitBreakerState.CLOSED) {
      if (this.consecutiveFailures >= this.circuitConfig.failureThreshold) {
        this.setState(CircuitBreakerState.OPEN);
      }
    }
  }

  private setState(newState: CircuitBreakerState): void {
    if (this.state !== newState) {
      const previousState = this.state;
      this.state = newState;
      this.stateChangedAt = new Date();

      this.logger.log(`Circuit breaker state changed: ${previousState} -> ${newState}`, {
        previousState,
        newState,
        consecutiveFailures: this.consecutiveFailures,
        consecutiveSuccesses: this.consecutiveSuccesses,
        timestamp: this.stateChangedAt.toISOString(),
      });

      this.emit('stateChanged', {
        previousState,
        newState,
        timestamp: this.stateChangedAt,
        consecutiveFailures: this.consecutiveFailures,
        consecutiveSuccesses: this.consecutiveSuccesses,
      });

      // Reset counters on state change
      if (newState === CircuitBreakerState.HALF_OPEN) {
        this.consecutiveSuccesses = 0;
      }
    }
  }

  private getRecentRequests(): { timestamp: number; success: boolean; responseTime: number }[] {
    const cutoff = Date.now() - this.circuitConfig.timeWindow;
    return this.requestWindow.filter(req => req.timestamp > cutoff);
  }

  private cleanupRequestWindow(): void {
    const cutoff = Date.now() - this.circuitConfig.timeWindow;
    this.requestWindow = this.requestWindow.filter(req => req.timestamp > cutoff);
  }

  private async initializeConnectionPool(): Promise<void> {
    this.logger.log('Initializing connection pool', {
      minConnections: this.poolConfig.minConnections,
      maxConnections: this.poolConfig.maxConnections,
      endpoints: this.parlantEndpoints,
    });

    // Create minimum connections
    for (let i = 0; i < this.poolConfig.minConnections; i++) {
      try {
        const connection = await this.createConnection();
        this.logger.debug(`Initial connection ${i + 1} created: ${connection.id}`);
      } catch (error) {
        this.logger.error(`Failed to create initial connection ${i + 1}:`, error);
      }
    }
  }

  private async createConnection(): Promise<any> {
    const connectionId = `conn_${Date.now()}_${Math.random().toString(36).substring(7)}`;

    // Select healthy endpoint
    const endpoint = this.selectHealthyEndpoint();

    // TODO: Create actual connection to Parlant API
    const connection = {
      id: connectionId,
      endpoint,
      createdAt: new Date(),
      lastUsed: new Date(),
      healthy: true,
    };

    this.connectionPool.set(connectionId, connection);
    return connection;
  }

  private findAvailableConnection(): any | null {
    for (const [id, connection] of this.connectionPool) {
      if (!this.activeConnections.has(id) && connection.healthy) {
        connection.lastUsed = new Date();
        return connection;
      }
    }
    return null;
  }

  private selectHealthyEndpoint(): string {
    const healthyEndpoints = this.parlantEndpoints.filter(endpoint => {
      const health = this.endpointHealth.get(endpoint);
      return !health || health.healthy;
    });

    if (healthyEndpoints.length === 0) {
      // Fallback to first endpoint if none are marked healthy
      return this.parlantEndpoints[0];
    }

    // Simple round-robin selection
    return healthyEndpoints[Math.floor(Math.random() * healthyEndpoints.length)];
  }

  private startHealthMonitoring(): void {
    // Initialize endpoint health
    this.parlantEndpoints.forEach(endpoint => {
      this.endpointHealth.set(endpoint, {
        url: endpoint,
        healthy: true,
        lastCheck: new Date(),
        responseTime: 0,
        consecutiveFailures: 0,
      });
    });

    // Periodic health checks
    setInterval(async () => {
      await this.performHealthChecks();
    }, this.poolConfig.healthCheckIntervalMs);
  }

  private async performHealthChecks(): Promise<void> {
    for (const endpoint of this.parlantEndpoints) {
      try {
        const startTime = performance.now();

        // TODO: Implement actual health check
        // const response = await fetch(`${endpoint}/health`);
        const responseTime = performance.now() - startTime;

        this.endpointHealth.set(endpoint, {
          url: endpoint,
          healthy: true,
          lastCheck: new Date(),
          responseTime,
          consecutiveFailures: 0,
        });

      } catch (error) {
        const currentHealth = this.endpointHealth.get(endpoint);
        this.endpointHealth.set(endpoint, {
          url: endpoint,
          healthy: false,
          lastCheck: new Date(),
          responseTime: 0,
          consecutiveFailures: (currentHealth?.consecutiveFailures || 0) + 1,
          lastError: error instanceof Error ? error.message : String(error),
        });

        this.logger.warn(`Health check failed for endpoint ${endpoint}:`, error);
      }
    }
  }

  private startPoolMaintenance(): void {
    // Clean up idle connections
    setInterval(() => {
      const now = Date.now();
      const idleThreshold = now - this.poolConfig.idleTimeoutMs;

      for (const [id, connection] of this.connectionPool) {
        if (!this.activeConnections.has(id) && 
            connection.lastUsed.getTime() < idleThreshold &&
            this.connectionPool.size > this.poolConfig.minConnections) {

          this.connectionPool.delete(id);
          this.logger.debug(`Removed idle connection: ${id}`);
        }
      }
    }, 60000); // Every minute

    // Log pool statistics
    setInterval(() => {
      const stats = this.getConnectionPoolStats();
      this.logger.log('Connection Pool Statistics', stats);
    }, 5 * 60 * 1000); // Every 5 minutes
  }
}

/**
 * Parlant Retry & Failover Service - Enterprise Resilience Strategy
 * 
 * Provides intelligent retry logic and failover strategies for Parlant validation
 * operations ensuring maximum availability and reliability under failure conditions.
 * 
 * Features:
 * - Exponential backoff with jitter for retry strategies
 * - Circuit breaker integration for intelligent failover
 * - Multi-endpoint failover with health-based routing
 * - Bulk operation retry with batch optimization
 * - Graceful degradation and fallback mechanisms
 * - Real-time retry analytics and optimization
 * 
 * Architecture: Multi-tier resilience with intelligent retry patterns
 * Availability: 99.9%+ target with automatic failover
 * Recovery: Sub-30 second failover time with graceful degradation
 */

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { EventEmitter } from 'events';
import { ParlantValidationRequest, ParlantValidationResponse, RiskLevel } from '../parlant-integration.service';
import { ParlantCircuitBreakerService, CircuitBreakerState } from './parlant-circuit-breaker.service';

// ===== RETRY & FAILOVER INTERFACES =====

/**
 * Retry configuration for different operation types
 */
export interface RetryConfig {
  readonly maxAttempts: number;
  readonly baseDelayMs: number;
  readonly maxDelayMs: number;
  readonly exponentialBase: number;
  readonly jitterEnabled: boolean;
  readonly retryOnErrors: string[];
  readonly timeoutMs: number;
  readonly circuitBreakerEnabled: boolean;
}

/**
 * Failover endpoint configuration
 */
export interface FailoverEndpoint {
  readonly url: string;
  readonly priority: number;
  readonly healthWeight: number;
  readonly maxConcurrentRequests: number;
  readonly enabled: boolean;
  readonly region?: string;
  readonly capabilities: string[];
}

/**
 * Retry attempt metadata
 */
export interface RetryAttempt {
  readonly attemptNumber: number;
  readonly timestamp: Date;
  readonly endpoint: string;
  readonly delayMs: number;
  readonly error?: Error;
  readonly responseTime?: number;
  readonly circuitBreakerState: CircuitBreakerState;
}

/**
 * Failover operation result
 */
export interface FailoverResult<T> {
  readonly success: boolean;
  readonly data?: T;
  readonly error?: Error;
  readonly totalAttempts: number;
  readonly totalTime: number;
  readonly successfulEndpoint?: string;
  readonly failedEndpoints: string[];
  readonly retryAttempts: RetryAttempt[];
  readonly degradedMode: boolean;
  readonly fallbackUsed: boolean;
}

/**
 * Bulk operation retry configuration
 */
export interface BulkRetryConfig {
  readonly batchSize: number;
  readonly maxConcurrentBatches: number;
  readonly failFastThreshold: number;
  readonly partialSuccessAllowed: boolean;
  readonly prioritizeHighRisk: boolean;
}

/**
 * Retry analytics and metrics
 */
export interface RetryAnalytics {
  readonly totalRetries: number;
  readonly successfulRetries: number;
  readonly failedRetries: number;
  readonly averageRetryCount: number;
  readonly averageRecoveryTime: number;
  readonly endpointSuccessRates: Map<string, number>;
  readonly errorDistribution: Map<string, number>;
  readonly timeDistribution: {
    immediate: number;
    fast: number;      // < 1s
    medium: number;    // 1-5s
    slow: number;      // > 5s
  };
}

/**
 * Graceful degradation strategy
 */
export interface DegradationStrategy {
  readonly level: 'NONE' | 'PARTIAL' | 'MINIMAL' | 'EMERGENCY';
  readonly cacheOnly: boolean;
  readonly reduceValidation: boolean;
  readonly allowBypass: boolean;
  readonly notifyUsers: boolean;
  readonly fallbackResponse: ParlantValidationResponse;
}

// ===== RETRY & FAILOVER SERVICE =====

@Injectable()
export class ParlantRetryFailoverService extends EventEmitter {
  private readonly logger = new Logger(ParlantRetryFailoverService.name);

  // Retry configurations by risk level
  private readonly retryConfigs: Map<RiskLevel, RetryConfig> = new Map([
