      circuitBreakerEnabled: true,
    }],
    [RiskLevel.LOW, {
      maxAttempts: 4,
      baseDelayMs: 200,
      maxDelayMs: 8000,
      exponentialBase: 2,
      jitterEnabled: true,
      retryOnErrors: ['TIMEOUT', 'CONNECTION_ERROR', 'RATE_LIMITED'],
      timeoutMs: 15000,
      circuitBreakerEnabled: true,
    }],
    [RiskLevel.MEDIUM, {
      maxAttempts: 3,
