      maxConcurrentRequests: 50,
      enabled: true,
      region: 'local',
      capabilities: ['validation', 'conversation', 'audit'],
    },
    // Additional endpoints would be configured here
  ];

  // Current endpoint health and load tracking
  private readonly endpointHealth = new Map<string, {
    healthy: boolean;
    responseTime: number;
    errorCount: number;
    successCount: number;
    concurrentRequests: number;
    lastCheck: Date;
  }>();

  // Retry analytics tracking
  private retryAnalytics: RetryAnalytics = {
    totalRetries: 0,
    successfulRetries: 0,
    failedRetries: 0,
    averageRetryCount: 0,
    averageRecoveryTime: 0,
    endpointSuccessRates: new Map(),
    errorDistribution: new Map(),
    timeDistribution: {
      immediate: 0,
      fast: 0,
      medium: 0,
      slow: 0,
    },
  };

  // Degradation strategies
  private readonly degradationStrategies: Map<string, DegradationStrategy> = new Map([
    ['circuit_open', {
      level: 'PARTIAL',
      cacheOnly: true,
      reduceValidation: true,
      allowBypass: false,
      notifyUsers: true,
      fallbackResponse: this.createFallbackResponse(),
    }],
    ['all_endpoints_down', {
      level: 'EMERGENCY',
      cacheOnly: true,
      reduceValidation: false,
      allowBypass: true,
      notifyUsers: true,
      fallbackResponse: this.createEmergencyFallbackResponse(),
    }],
  ]);

  // Bulk operation configuration
  private readonly bulkRetryConfig: BulkRetryConfig = {
    batchSize: 10,
    maxConcurrentBatches: 5,
    failFastThreshold: 0.5, // 50% failure rate
    partialSuccessAllowed: true,
    prioritizeHighRisk: true,
  };

  constructor(
    private readonly configService: ConfigService,
    private readonly circuitBreakerService: ParlantCircuitBreakerService
  ) {
    super();

    const operationId = `retry_failover_init_${Date.now()}_${Math.random().toString(36).substring(7)}`;

    this.logger.log(`[${operationId}] Initializing Parlant Retry & Failover Service`, {
      retryConfigs: Object.fromEntries(this.retryConfigs),
      failoverEndpoints: this.failoverEndpoints.map(e => ({ url: e.url, priority: e.priority })),
      bulkRetryConfig: this.bulkRetryConfig,
      degradationStrategies: Array.from(this.degradationStrategies.keys()),
    });

    // Initialize endpoint health tracking
    this.initializeEndpointHealth();

    // Start health monitoring
    this.startHealthMonitoring();

    // Listen to circuit breaker events
    this.circuitBreakerService.on('stateChanged', (event) => {
      this.handleCircuitBreakerStateChange(event);
    });
  }

  /**
   * Execute validation with comprehensive retry and failover logic
   * 
   * @param request - Validation request
   * @param operation - Operation function to execute
   * @returns Result with retry and failover metadata
   */
  async executeWithRetryFailover<T>(
    request: ParlantValidationRequest,
    operation: (endpoint: string) => Promise<T>
  ): Promise<FailoverResult<T>> {
    const startTime = performance.now();
    const config = this.getRetryConfig(request.riskLevel);
    const retryAttempts: RetryAttempt[] = [];
    const failedEndpoints: string[] = [];

    let lastError: Error | undefined;
    let currentAttempt = 0;

    this.logger.debug(`[${request.operationId}] Starting retry/failover execution`, {
      operationId: request.operationId,
      riskLevel: request.riskLevel,
      maxAttempts: config.maxAttempts,
      availableEndpoints: this.getHealthyEndpoints().length,
    });

    // Check for degraded mode conditions
    const degradationStrategy = this.assessDegradationNeed();
    if (degradationStrategy && degradationStrategy.level !== 'NONE') {
      return this.executeDegradedOperation(request, degradationStrategy, startTime);
    }

    // Attempt operation with retry logic
    while (currentAttempt < config.maxAttempts) {
      currentAttempt++;

      // Select best available endpoint
      const endpoint = this.selectOptimalEndpoint(failedEndpoints);
      if (!endpoint) {
        break; // No healthy endpoints available
      }

      const attemptStartTime = performance.now();

      try {
        // Apply circuit breaker protection if enabled
        if (config.circuitBreakerEnabled) {
          const circuitResult = await this.circuitBreakerService.executeWithProtection(
            () => operation(endpoint.url),
            request.operationId
          );

          if (circuitResult.success) {
            // Success - update analytics and return
            const totalTime = performance.now() - startTime;
            this.updateSuccessAnalytics(currentAttempt, totalTime, endpoint.url);

            this.logger.debug(`[${request.operationId}] Operation succeeded on attempt ${currentAttempt}`, {
              endpoint: endpoint.url,
              totalTime: `${totalTime.toFixed(2)}ms`,
              attempts: currentAttempt,
            });

            return {
              success: true,
              data: circuitResult.data,
              totalAttempts: currentAttempt,
              totalTime,
              successfulEndpoint: endpoint.url,
              failedEndpoints,
              retryAttempts,
              degradedMode: false,
              fallbackUsed: false,
            };
          } else {
            lastError = circuitResult.error;
          }
        } else {
          // Direct operation execution
          const result = await this.executeWithTimeout(
            () => operation(endpoint.url),
            config.timeoutMs,
            request.operationId
          );

          // Success
          const totalTime = performance.now() - startTime;
          this.updateSuccessAnalytics(currentAttempt, totalTime, endpoint.url);

          return {
            success: true,
            data: result,
            totalAttempts: currentAttempt,
            totalTime,
            successfulEndpoint: endpoint.url,
            failedEndpoints,
            retryAttempts,
            degradedMode: false,
            fallbackUsed: false,
          };
        }

      } catch (error) {
        lastError = error as Error;
        const attemptTime = performance.now() - attemptStartTime;

        // Record failed attempt
        const retryAttempt: RetryAttempt = {
          attemptNumber: currentAttempt,
          timestamp: new Date(),
          endpoint: endpoint.url,
          delayMs: 0,
          error: lastError,
          responseTime: attemptTime,
          circuitBreakerState: this.circuitBreakerService.getCircuitBreakerStats().state,
        };

        retryAttempts.push(retryAttempt);
        failedEndpoints.push(endpoint.url);

        // Update endpoint health
        this.updateEndpointHealth(endpoint.url, false, attemptTime);

        this.logger.warn(`[${request.operationId}] Attempt ${currentAttempt} failed`, {
          endpoint: endpoint.url,
          error: lastError.message,
          attemptTime: `${attemptTime.toFixed(2)}ms`,
          remainingAttempts: config.maxAttempts - currentAttempt,
        });

        // Check if we should retry this error type
        if (!this.shouldRetryError(lastError, config)) {
          this.logger.debug(`[${request.operationId}] Error type not retryable: ${lastError.message}`);
          break;
        }

        // Apply delay before next attempt (if not last attempt)
        if (currentAttempt < config.maxAttempts) {
          const delayMs = this.calculateRetryDelay(currentAttempt, config);
          retryAttempt.delayMs = delayMs;

          if (delayMs > 0) {
            this.logger.debug(`[${request.operationId}] Delaying ${delayMs}ms before retry ${currentAttempt + 1}`);
            await this.delay(delayMs);
          }
        }
      }
    }

    // All attempts failed - update analytics and return failure
    const totalTime = performance.now() - startTime;
    this.updateFailureAnalytics(currentAttempt, totalTime);

    this.logger.error(`[${request.operationId}] All retry attempts failed`, {
      totalAttempts: currentAttempt,
      totalTime: `${totalTime.toFixed(2)}ms`,
      lastError: lastError?.message,
      failedEndpoints,
    });

    // Attempt fallback/degraded response
    const fallbackResult = await this.attemptFallbackResponse(request);

    return {
      success: false,
      error: lastError || new Error('All retry attempts exhausted'),
      totalAttempts: currentAttempt,
      totalTime,
      failedEndpoints,
      retryAttempts,
      degradedMode: fallbackResult.degradedMode,
      fallbackUsed: fallbackResult.fallbackUsed,
      data: fallbackResult.data,
    };
  }

  /**
   * Execute bulk operations with intelligent retry and batching
   * 
   * @param requests - Array of validation requests
   * @param operation - Operation function for individual requests
   * @returns Bulk operation results with retry analytics
   */
  async executeBulkWithRetry<T>(
    requests: ParlantValidationRequest[],
    operation: (request: ParlantValidationRequest, endpoint: string) => Promise<T>
  ): Promise<{
    results: Array<FailoverResult<T> | null>;
    summary: {
      totalRequests: number;
      successfulRequests: number;
      failedRequests: number;
      totalRetries: number;
      averageTime: number;
      partialSuccess: boolean;
    };
  }> {
    const startTime = performance.now();
    const totalRequests = requests.length;

    this.logger.log(`Starting bulk retry operation for ${totalRequests} requests`, {
      batchSize: this.bulkRetryConfig.batchSize,
      maxConcurrentBatches: this.bulkRetryConfig.maxConcurrentBatches,
      prioritizeHighRisk: this.bulkRetryConfig.prioritizeHighRisk,
    });

    // Sort requests by priority if enabled
    const sortedRequests = this.bulkRetryConfig.prioritizeHighRisk
      ? this.sortRequestsByPriority(requests)
      : requests;

    // Split into batches
    const batches = this.createBatches(sortedRequests, this.bulkRetryConfig.batchSize);
    const results: Array<FailoverResult<T> | null> = new Array(totalRequests).fill(null);

    let processedBatches = 0;
    let successfulRequests = 0;
    let failedRequests = 0;
    let totalRetries = 0;

    // Process batches with concurrency control
    for (let i = 0; i < batches.length; i += this.bulkRetryConfig.maxConcurrentBatches) {
      const batchGroup = batches.slice(i, i + this.bulkRetryConfig.maxConcurrentBatches);

      const batchPromises = batchGroup.map(async (batch, batchIndex) => {
        const actualBatchIndex = i + batchIndex;

        const batchResults = await Promise.allSettled(
          batch.map(async (request, requestIndex) => {
            const globalIndex = actualBatchIndex * this.bulkRetryConfig.batchSize + requestIndex;

            try {
              const result = await this.executeWithRetryFailover(
                request,
                (endpoint) => operation(request, endpoint)
              );

              totalRetries += result.totalAttempts - 1; // Exclude initial attempt

              if (result.success) {
                successfulRequests++;
              } else {
                failedRequests++;
              }

              return { result, globalIndex };
            } catch (error) {
              failedRequests++;
              return {
                result: {
                  success: false,
                  error: error as Error,
                  totalAttempts: 1,
                  totalTime: 0,
                  failedEndpoints: [],
                  retryAttempts: [],
                  degradedMode: false,
                  fallbackUsed: false,
                } as FailoverResult<T>,
                globalIndex,
              };
            }
          })
        );

        // Update results array
        batchResults.forEach((result) => {
          if (result.status === 'fulfilled') {
            results[result.value.globalIndex] = result.value.result;
          }
        });

        processedBatches++;

        // Check fail-fast threshold
        const failureRate = failedRequests / (successfulRequests + failedRequests);
        if (failureRate > this.bulkRetryConfig.failFastThreshold && processedBatches > 2) {
          this.logger.warn(`Bulk operation exceeding failure threshold: ${(failureRate * 100).toFixed(1)}%`);

          if (!this.bulkRetryConfig.partialSuccessAllowed) {
            throw new Error(`Bulk operation failed: failure rate ${(failureRate * 100).toFixed(1)}% exceeds threshold`);
          }
        }
      });

      await Promise.all(batchPromises);
    }

    const totalTime = performance.now() - startTime;
    const averageTime = totalTime / totalRequests;

    const summary = {
      totalRequests,
      successfulRequests,
      failedRequests,
      totalRetries,
      averageTime,
      partialSuccess: successfulRequests > 0 && failedRequests > 0,
    };

    this.logger.log('Bulk retry operation completed', {
      ...summary,
      totalTime: `${totalTime.toFixed(2)}ms`,
      successRate: `${((successfulRequests / totalRequests) * 100).toFixed(1)}%`,
    });

    return { results, summary };
  }

  /**
   * Get current retry and failover analytics
   * 
   * @returns Comprehensive retry analytics
   */
  getRetryAnalytics(): RetryAnalytics {
    return { ...this.retryAnalytics };
  }

  /**
   * Force endpoint health status (for testing/admin)
   * 
   * @param endpoint - Endpoint URL
   * @param healthy - Health status
   * @param reason - Reason for status change
   */
  forceEndpointHealth(endpoint: string, healthy: boolean, reason: string): void {
    const health = this.endpointHealth.get(endpoint);
    if (health) {
      health.healthy = healthy;
      health.lastCheck = new Date();

      this.logger.warn(`Endpoint health forced: ${endpoint} -> ${healthy ? 'HEALTHY' : 'UNHEALTHY'}`, {
        endpoint,
        healthy,
        reason,
        timestamp: new Date().toISOString(),
      });

      this.emit('endpointHealthChanged', {
        endpoint,
        healthy,
        reason: `FORCED: ${reason}`,
        timestamp: new Date(),
      });
    }
  }

  // ===== PRIVATE HELPER METHODS =====

  private getRetryConfig(riskLevel: RiskLevel): RetryConfig {
    return this.retryConfigs.get(riskLevel) || this.retryConfigs.get(RiskLevel.MEDIUM)!;
  }

  private getHealthyEndpoints(): FailoverEndpoint[] {
    return this.failoverEndpoints.filter(endpoint => {
      const health = this.endpointHealth.get(endpoint.url);
      return endpoint.enabled && (!health || health.healthy);
    });
  }

  private selectOptimalEndpoint(excludeEndpoints: string[]): FailoverEndpoint | null {
    const healthyEndpoints = this.getHealthyEndpoints()
      .filter(endpoint => !excludeEndpoints.includes(endpoint.url));

    if (healthyEndpoints.length === 0) {
      return null;
    }

    // Select based on priority and current load
    return healthyEndpoints.reduce((best, current) => {
      const currentHealth = this.endpointHealth.get(current.url);
      const bestHealth = this.endpointHealth.get(best.url);

      // Prioritize by priority first, then by load and response time
      if (current.priority < best.priority) return current;
      if (current.priority > best.priority) return best;

      // Same priority - select based on performance
      const currentLoad = currentHealth ? currentHealth.concurrentRequests / current.maxConcurrentRequests : 0;
      const bestLoad = bestHealth ? bestHealth.concurrentRequests / best.maxConcurrentRequests : 0;

      return currentLoad < bestLoad ? current : best;
    });
  }

  private shouldRetryError(error: Error, config: RetryConfig): boolean {
    const errorType = this.categorizeError(error);
    return config.retryOnErrors.includes(errorType);
  }

  private categorizeError(error: Error): string {
    const message = error.message.toLowerCase();

    if (message.includes('timeout') || message.includes('timed out')) {
      return 'TIMEOUT';
    }
    if (message.includes('connection') || message.includes('network')) {
      return 'CONNECTION_ERROR';
    }
    if (message.includes('rate limit') || message.includes('too many requests')) {
      return 'RATE_LIMITED';
    }
    if (message.includes('server error') || message.includes('internal error')) {
      return 'SERVER_ERROR';
    }

    return 'UNKNOWN_ERROR';
  }

  private calculateRetryDelay(attemptNumber: number, config: RetryConfig): number {
    if (config.baseDelayMs === 0) return 0;

    // Calculate exponential backoff
    let delay = config.baseDelayMs * Math.pow(config.exponentialBase, attemptNumber - 1);

    // Apply maximum delay limit
    delay = Math.min(delay, config.maxDelayMs);

    // Add jitter if enabled
    if (config.jitterEnabled) {
      const jitter = delay * 0.1 * Math.random(); // Up to 10% jitter
      delay += jitter;
    }

    return Math.floor(delay);
  }

  private async executeWithTimeout<T>(
    operation: () => Promise<T>,
    timeoutMs: number,
    operationId: string
  ): Promise<T> {
    return Promise.race([
      operation(),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error(`Operation timeout after ${timeoutMs}ms`)), timeoutMs)
      ),
    ]);
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  private updateSuccessAnalytics(attempts: number, totalTime: number, endpoint: string): void {
    this.retryAnalytics.totalRetries += (attempts - 1);
    this.retryAnalytics.successfulRetries++;

    // Update average retry count
    const totalOperations = this.retryAnalytics.successfulRetries + this.retryAnalytics.failedRetries;
    this.retryAnalytics.averageRetryCount = 
      (this.retryAnalytics.averageRetryCount * (totalOperations - 1) + (attempts - 1)) / totalOperations;

    // Update endpoint success rate
    const currentRate = this.retryAnalytics.endpointSuccessRates.get(endpoint) || 0;
    this.retryAnalytics.endpointSuccessRates.set(endpoint, currentRate + 1);

    // Update time distribution
    this.updateTimeDistribution(totalTime);
  }

  private updateFailureAnalytics(attempts: number, totalTime: number): void {
    this.retryAnalytics.totalRetries += (attempts - 1);
    this.retryAnalytics.failedRetries++;

    // Update average retry count
    const totalOperations = this.retryAnalytics.successfulRetries + this.retryAnalytics.failedRetries;
    this.retryAnalytics.averageRetryCount = 
      (this.retryAnalytics.averageRetryCount * (totalOperations - 1) + (attempts - 1)) / totalOperations;

    // Update time distribution
    this.updateTimeDistribution(totalTime);
  }

  private updateTimeDistribution(totalTime: number): void {
    if (totalTime < 100) {
      this.retryAnalytics.timeDistribution.immediate++;
    } else if (totalTime < 1000) {
      this.retryAnalytics.timeDistribution.fast++;
    } else if (totalTime < 5000) {
      this.retryAnalytics.timeDistribution.medium++;
    } else {
      this.retryAnalytics.timeDistribution.slow++;
    }
  }

  private updateEndpointHealth(endpoint: string, success: boolean, responseTime: number): void {
    const health = this.endpointHealth.get(endpoint);
    if (health) {
      if (success) {
        health.successCount++;
        health.healthy = true;
        health.errorCount = Math.max(0, health.errorCount - 1); // Gradual recovery
      } else {
        health.errorCount++;
        if (health.errorCount > 5) {
          health.healthy = false;
        }
      }

      health.responseTime = (health.responseTime + responseTime) / 2; // Moving average
      health.lastCheck = new Date();
    }
  }

  private assessDegradationNeed(): DegradationStrategy | null {
    const circuitStats = this.circuitBreakerService.getCircuitBreakerStats();

    if (circuitStats.state === CircuitBreakerState.OPEN) {
      return this.degradationStrategies.get('circuit_open') || null;
    }

    const healthyEndpoints = this.getHealthyEndpoints();
    if (healthyEndpoints.length === 0) {
      return this.degradationStrategies.get('all_endpoints_down') || null;
    }

    return null;
  }

  private async executeDegradedOperation<T>(
    request: ParlantValidationRequest,
    strategy: DegradationStrategy,
    startTime: number
  ): Promise<FailoverResult<T>> {
    const totalTime = performance.now() - startTime;

    this.logger.warn(`Executing in degraded mode: ${strategy.level}`, {
      operationId: request.operationId,
      strategy: strategy.level,
      cacheOnly: strategy.cacheOnly,
      allowBypass: strategy.allowBypass,
    });

    return {
      success: true,
      data: strategy.fallbackResponse as any, // Type assertion for generic
      totalAttempts: 0,
      totalTime,
      failedEndpoints: [],
      retryAttempts: [],
      degradedMode: true,
      fallbackUsed: true,
    };
  }

  private async attemptFallbackResponse(request: ParlantValidationRequest): Promise<{
    degradedMode: boolean;
    fallbackUsed: boolean;
    data?: any;
  }> {
    // Try cache-only response for low-risk operations
    if (request.riskLevel === RiskLevel.MINIMAL || request.riskLevel === RiskLevel.LOW) {
      return {
        degradedMode: true,
        fallbackUsed: true,
        data: this.createFallbackResponse(),
      };
    }

    return {
      degradedMode: false,
      fallbackUsed: false,
    };
  }

  private createFallbackResponse(): ParlantValidationResponse {
    return {
      approved: false,
      conversationId: `fallback_${Date.now()}`,
      validationTimestamp: new Date(),
      reasoning: 'Fallback response due to service degradation - operation blocked for safety',
      confidence: 0,
      suggestedAlternatives: ['Retry operation later', 'Contact system administrator'],
    };
  }

  private createEmergencyFallbackResponse(): ParlantValidationResponse {
    return {
      approved: false,
      conversationId: `emergency_${Date.now()}`,
      validationTimestamp: new Date(),
      reasoning: 'Emergency fallback - validation service unavailable',
      confidence: 0,
      suggestedAlternatives: ['Service temporarily unavailable', 'Retry in a few minutes'],
    };
  }

  private sortRequestsByPriority(requests: ParlantValidationRequest[]): ParlantValidationRequest[] {
    const priorityOrder = [RiskLevel.CRITICAL, RiskLevel.HIGH, RiskLevel.MEDIUM, RiskLevel.LOW, RiskLevel.MINIMAL];

    return requests.sort((a, b) => {
      const aPriority = priorityOrder.indexOf(a.riskLevel);
      const bPriority = priorityOrder.indexOf(b.riskLevel);
      return aPriority - bPriority;
    });
  }

  private createBatches<T>(items: T[], batchSize: number): T[][] {
    const batches: T[][] = [];
    for (let i = 0; i < items.length; i += batchSize) {
      batches.push(items.slice(i, i + batchSize));
    }
    return batches;
  }

  private initializeEndpointHealth(): void {
    this.failoverEndpoints.forEach(endpoint => {
      this.endpointHealth.set(endpoint.url, {
        healthy: true,
        responseTime: 0,
        errorCount: 0,
        successCount: 0,
        concurrentRequests: 0,
        lastCheck: new Date(),
      });
    });
  }

  private startHealthMonitoring(): void {
    setInterval(async () => {
      for (const endpoint of this.failoverEndpoints) {
        try {
          const startTime = performance.now();

          // TODO: Implement actual health check
          // const response = await fetch(`${endpoint.url}/health`, { timeout: 5000 });
          const responseTime = performance.now() - startTime;

          this.updateEndpointHealth(endpoint.url, true, responseTime);

        } catch (error) {
          this.updateEndpointHealth(endpoint.url, false, 0);
          this.logger.debug(`Health check failed for ${endpoint.url}:`, error);
        }
      }
    }, 30000); // Every 30 seconds

    // Log analytics every 5 minutes
    setInterval(() => {
      this.logger.log('Retry & Failover Analytics', this.getRetryAnalytics());
    }, 5 * 60 * 1000);
  }

  private handleCircuitBreakerStateChange(event: any): void {
    this.logger.log(`Circuit breaker state changed: ${event.previousState} -> ${event.newState}`, {
      previousState: event.previousState,
      newState: event.newState,
      timestamp: event.timestamp,
    });

    // Trigger degradation assessment if circuit opens
    if (event.newState === CircuitBreakerState.OPEN) {
      this.emit('degradationTriggered', {
        reason: 'circuit_breaker_open',
        timestamp: new Date(),
      });
    }
  }
}

/**
 * Parlant Health & Metrics Validation Service
 *
 * Comprehensive conversational validation service for all health monitoring and metrics
 * operations in the Bytebot package. Provides risk-appropriate validation based on
 * operation criticality with full audit trail support.
 *
 * Features:
 * - Risk-based conversational validation (LOW/MEDIUM/HIGH/CRITICAL)
 * - Health check operation validation with context awareness
 * - Metrics collection validation with performance impact assessment
 * - Alert generation validation with escalation policies
 * - Comprehensive audit trail for all health/monitoring operations
 * - Performance-optimized validation for high-frequency operations
 * - Intelligent caching for repetitive health checks
 *
 * Risk Levels:
 * - LOW: Basic metrics collection, routine health checks
 * - MEDIUM: System status changes, performance metrics
 * - HIGH: Critical alerts, diagnostic operations
 * - CRITICAL: System shutdown, emergency responses
 *
 * @author Claude Code - Agent 4 (Health & Metrics Parlant Integration)
 * @version 1.0.0
 */

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

// ===== VALIDATION INTERFACES =====

/**
 * Risk level for health/metrics operations
 */
export enum HealthMetricsRiskLevel {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM', 
  HIGH = 'HIGH',
  CRITICAL = 'CRITICAL',
}

/**
 * Health operation types for validation
 */
export enum HealthOperationType {
  BASIC_HEALTH_CHECK = 'BASIC_HEALTH_CHECK',
  DETAILED_STATUS = 'DETAILED_STATUS',
  LIVENESS_PROBE = 'LIVENESS_PROBE',
  READINESS_PROBE = 'READINESS_PROBE',
  STARTUP_PROBE = 'STARTUP_PROBE',
  PROCESS_HEALTH = 'PROCESS_HEALTH',
  DATABASE_HEALTH = 'DATABASE_HEALTH',
  EXTERNAL_SERVICES = 'EXTERNAL_SERVICES',
  MODULE_INITIALIZATION = 'MODULE_INITIALIZATION',
  SYSTEM_RESOURCES = 'SYSTEM_RESOURCES',
  DEPENDENCY_CHECK = 'DEPENDENCY_CHECK',
}

/**
 * Metrics operation types for validation
 */
export enum MetricsOperationType {
  PROMETHEUS_COLLECTION = 'PROMETHEUS_COLLECTION',
  API_REQUEST_TRACKING = 'API_REQUEST_TRACKING',
  TASK_PROCESSING = 'TASK_PROCESSING',
  COMPUTER_USE_METRICS = 'COMPUTER_USE_METRICS',
  WEBSOCKET_METRICS = 'WEBSOCKET_METRICS',
  DATABASE_METRICS = 'DATABASE_METRICS',
  CACHE_METRICS = 'CACHE_METRICS',
  COMPRESSION_METRICS = 'COMPRESSION_METRICS',
  SYSTEM_METRICS = 'SYSTEM_METRICS',
  PERFORMANCE_BASELINE = 'PERFORMANCE_BASELINE',
}

/**
 * Alert operation types for validation
 */
export enum AlertOperationType {
  CREATE_ALERT = 'CREATE_ALERT',
  ACKNOWLEDGE_ALERT = 'ACKNOWLEDGE_ALERT',
  ESCALATE_ALERT = 'ESCALATE_ALERT',
  RESOLVE_ALERT = 'RESOLVE_ALERT',
  EMERGENCY_NOTIFICATION = 'EMERGENCY_NOTIFICATION',
  SLA_VIOLATION = 'SLA_VIOLATION',
}

/**
 * Validation request context
 */
export interface HealthMetricsValidationContext {
  operationType: HealthOperationType | MetricsOperationType | AlertOperationType;
  riskLevel: HealthMetricsRiskLevel;
  operationId: string;
  userId?: string;
  userRole?: string;
  parameters: Record<string, unknown>;
  systemContext: {
    currentHealth: string;
    activeAlerts: number;
    systemLoad: number;
    criticalOperationsActive: boolean;
  };
  metadata: {
    endpoint?: string;
    method?: string;
    duration?: number;
    frequency?: 'once' | 'periodic' | 'high-frequency';
  };
}

/**
 * Validation result
 */
export interface HealthMetricsValidationResult {
  approved: boolean;
  riskLevel: HealthMetricsRiskLevel;
  conversationId: string;
  reason?: string;
  recommendations?: string[];
  auditTrail: {
    operationId: string;
    timestamp: Date;
    validator: string;
    decision: 'APPROVED' | 'REJECTED' | 'ESCALATED';
    reasoning: string;
    evidence: Record<string, unknown>;
  };
  performanceImpact: {
    validationDuration: number;
    cacheHit: boolean;
    optimization: string;
  };
}

/**
 * Cached validation decision
 */
interface CachedValidation {
  result: HealthMetricsValidationResult;
  expiry: Date;
  hitCount: number;
}

/**
 * Risk assessment criteria
 */
interface RiskAssessment {
  level: HealthMetricsRiskLevel;
  factors: string[];
  requiresApproval: boolean;
  escalationRequired: boolean;
  auditRequired: boolean;
}

// ===== MAIN SERVICE =====

@Injectable()
export class ParlantHealthMetricsValidationService {
  private readonly logger = new Logger(ParlantHealthMetricsValidationService.name);

  /** Validation cache for performance optimization */
  private readonly validationCache = new Map<string, CachedValidation>();

  /** Operation risk mappings */
  private readonly operationRiskMap = new Map<string, HealthMetricsRiskLevel>();

  /** Performance metrics */
  private validationMetrics = {
    totalValidations: 0,
    cacheHits: 0,
    approvalRate: 0,
    averageValidationTime: 0,
  };

  /** Mock Parlant client - In production, this would be actual Parlant integration */
  private readonly parlantClient = {
    createValidationSession: async (context: any) => ({
      id: `validation_${Date.now()}_${Math.random().toString(36).substring(7)}`,
      validate: async () => ({ approved: true, reason: 'Validated through conversational AI' }),
      explainAction: async () => `Health/metrics operation: ${context.operationType}`,
      logAudit: async (audit: any) => this.logger.debug('Parlant audit logged', audit),
    }),
  };

  constructor(private readonly configService: ConfigService) {
    this.initializeRiskMappings();
    this.logger.log('Parlant Health & Metrics Validation Service initialized');
    this.logger.log('Risk-based validation system active with performance optimization');
  }

  // ===== PRIMARY VALIDATION METHODS =====

  /**
   * Validate health operation with conversational AI
   */
  async validateHealthOperation(
    operationType: HealthOperationType,
    parameters: Record<string, unknown>,
    userContext?: { userId?: string; userRole?: string },
  ): Promise<HealthMetricsValidationResult> {
    const operationId = `health_${Date.now()}_${Math.random().toString(36).substring(7)}`;
    const startTime = Date.now();

    this.logger.debug(`[${operationId}] Validating health operation: ${operationType}`, {
      operationId,
      operationType,
      parametersCount: Object.keys(parameters).length,
      userId: userContext?.userId,
    });

    try {
      // Assess risk level for this operation
      const riskAssessment = this.assessOperationRisk(operationType, parameters);

      // Check cache for repetitive operations
      const cacheKey = this.generateCacheKey(operationType, parameters, riskAssessment.level);
      const cachedResult = this.getCachedValidation(cacheKey);

      if (cachedResult) {
        const duration = Date.now() - startTime;
        this.updateValidationMetrics(duration, true, true);

        this.logger.debug(`[${operationId}] Using cached validation result`, {
          operationId,
          cacheHit: true,
          validationDuration: duration,
        });

        return {
          ...cachedResult.result,
          operationId,
          performanceImpact: {
            validationDuration: duration,
            cacheHit: true,
            optimization: 'cache_hit',
          },
        };
      }

      // Create validation context
      const validationContext: HealthMetricsValidationContext = {
        operationType,
        riskLevel: riskAssessment.level,
        operationId,
        userId: userContext?.userId,
        userRole: userContext?.userRole,
        parameters,
        systemContext: await this.getSystemContext(),
        metadata: {
          frequency: this.determineOperationFrequency(operationType),
        },
      };

      // Perform conversational validation based on risk level
      const validationResult = await this.performConversationalValidation(
        validationContext,
        riskAssessment,
      );

      // Cache result for future use (if applicable)
      if (this.shouldCacheValidation(operationType, riskAssessment.level)) {
        this.cacheValidation(cacheKey, validationResult);
      }

      const duration = Date.now() - startTime;
      this.updateValidationMetrics(duration, false, validationResult.approved);

      this.logger.debug(`[${operationId}] Health operation validation completed`, {
        operationId,
        approved: validationResult.approved,
        riskLevel: riskAssessment.level,
        validationDuration: duration,
      });

      return validationResult;

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error(`[${operationId}] Health validation failed: ${errorMessage}`, {
        operationId,
        operationType,
        error: errorMessage,
      });

      // Return safe default for critical health operations
      return this.createFailsafeValidation(operationId, operationType, errorMessage);
    }
  }

  /**
   * Validate metrics operation with conversational AI
   */
  async validateMetricsOperation(
    operationType: MetricsOperationType,
    parameters: Record<string, unknown>,
    userContext?: { userId?: string; userRole?: string },
  ): Promise<HealthMetricsValidationResult> {
    const operationId = `metrics_${Date.now()}_${Math.random().toString(36).substring(7)}`;
    const startTime = Date.now();

    this.logger.debug(`[${operationId}] Validating metrics operation: ${operationType}`, {
      operationId,
      operationType,
      parametersCount: Object.keys(parameters).length,
      userId: userContext?.userId,
    });

    try {
      // Most metrics operations are LOW risk unless they involve critical system changes
      const riskLevel = this.getMetricsOperationRiskLevel(operationType, parameters);

      // For low-risk, high-frequency metrics operations, use optimized validation
      if (riskLevel === HealthMetricsRiskLevel.LOW && this.isHighFrequencyOperation(operationType)) {
        return this.performOptimizedValidation(operationId, operationType, parameters);
      }

      // Full validation for higher-risk metrics operations
      const riskAssessment = this.assessOperationRisk(operationType, parameters);

      const validationContext: HealthMetricsValidationContext = {
        operationType,
        riskLevel,
        operationId,
        userId: userContext?.userId,
        userRole: userContext?.userRole,
        parameters,
        systemContext: await this.getSystemContext(),
        metadata: {
          frequency: this.determineOperationFrequency(operationType),
        },
      };

      const validationResult = await this.performConversationalValidation(
        validationContext,
        riskAssessment,
      );

      const duration = Date.now() - startTime;
      this.updateValidationMetrics(duration, false, validationResult.approved);

      this.logger.debug(`[${operationId}] Metrics operation validation completed`, {
        operationId,
        approved: validationResult.approved,
        riskLevel,
        validationDuration: duration,
      });

      return validationResult;

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error(`[${operationId}] Metrics validation failed: ${errorMessage}`, {
        operationId,
        operationType,
        error: errorMessage,
      });

      return this.createFailsafeValidation(operationId, operationType, errorMessage);
    }
  }

  /**
   * Validate alert operation with conversational AI
   */
  async validateAlertOperation(
    operationType: AlertOperationType,
    parameters: Record<string, unknown>,
    userContext?: { userId?: string; userRole?: string },
  ): Promise<HealthMetricsValidationResult> {
    const operationId = `alert_${Date.now()}_${Math.random().toString(36).substring(7)}`;
    const startTime = Date.now();

    this.logger.debug(`[${operationId}] Validating alert operation: ${operationType}`, {
      operationId,
      operationType,
      severity: parameters.severity,
      component: parameters.component,
      userId: userContext?.userId,
    });

    try {
      // Alert operations require careful validation based on severity
      const riskLevel = this.getAlertOperationRiskLevel(operationType, parameters);
      const riskAssessment = this.assessOperationRisk(operationType, parameters);

      const validationContext: HealthMetricsValidationContext = {
        operationType,
        riskLevel,
        operationId,
        userId: userContext?.userId,
        userRole: userContext?.userRole,
        parameters,
        systemContext: await this.getSystemContext(),
        metadata: {
          frequency: 'once', // Alerts are typically one-time events
        },
      };

      const validationResult = await this.performConversationalValidation(
        validationContext,
        riskAssessment,
      );

      const duration = Date.now() - startTime;
      this.updateValidationMetrics(duration, false, validationResult.approved);

      this.logger.debug(`[${operationId}] Alert operation validation completed`, {
        operationId,
        approved: validationResult.approved,
        riskLevel,
        alertSeverity: parameters.severity,
        validationDuration: duration,
      });

      return validationResult;

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error(`[${operationId}] Alert validation failed: ${errorMessage}`, {
        operationId,
        operationType,
        error: errorMessage,
      });

      return this.createFailsafeValidation(operationId, operationType, errorMessage);
    }
  }

  // ===== RISK ASSESSMENT =====

  /**
   * Assess operation risk level
   */
  private assessOperationRisk(
    operationType: HealthOperationType | MetricsOperationType | AlertOperationType,
    parameters: Record<string, unknown>,
  ): RiskAssessment {
    const baseRisk = this.operationRiskMap.get(operationType.toString()) || HealthMetricsRiskLevel.MEDIUM;
    const factors: string[] = [];

    // Analyze parameters for risk factors
    if (parameters.severity === 'EMERGENCY' || parameters.severity === 'CRITICAL') {
      factors.push('Critical severity level');
      return {
        level: HealthMetricsRiskLevel.CRITICAL,
        factors,
        requiresApproval: true,
        escalationRequired: true,
        auditRequired: true,
      };
    }

    if (parameters.component === 'database' || parameters.component === 'authentication') {
      factors.push('Critical system component');
    }

    if (parameters.frequency === 'high-frequency') {
      factors.push('High frequency operation - optimized validation');
    }

    return {
      level: baseRisk,
      factors,
      requiresApproval: baseRisk !== HealthMetricsRiskLevel.LOW,
      escalationRequired: baseRisk === HealthMetricsRiskLevel.CRITICAL,
      auditRequired: true,
    };
  }

  /**
   * Get metrics operation risk level
   */
  private getMetricsOperationRiskLevel(
    operationType: MetricsOperationType,
    parameters: Record<string, unknown>,
  ): HealthMetricsRiskLevel {
    // Most metrics collection is low risk
    const lowRiskOperations = [
      MetricsOperationType.PROMETHEUS_COLLECTION,
      MetricsOperationType.API_REQUEST_TRACKING,
      MetricsOperationType.SYSTEM_METRICS,
    ];

    if (lowRiskOperations.includes(operationType)) {
      return HealthMetricsRiskLevel.LOW;
    }

    // Performance-impacting operations are medium risk
    const mediumRiskOperations = [
      MetricsOperationType.DATABASE_METRICS,
      MetricsOperationType.PERFORMANCE_BASELINE,
    ];

    if (mediumRiskOperations.includes(operationType)) {
      return HealthMetricsRiskLevel.MEDIUM;
    }

    return HealthMetricsRiskLevel.LOW;
  }

  /**
   * Get alert operation risk level
   */
  private getAlertOperationRiskLevel(
    operationType: AlertOperationType,
    parameters: Record<string, unknown>,
  ): HealthMetricsRiskLevel {
    // Emergency operations are critical
    if (operationType === AlertOperationType.EMERGENCY_NOTIFICATION) {
      return HealthMetricsRiskLevel.CRITICAL;
    }

    // Alert creation based on severity
    if (operationType === AlertOperationType.CREATE_ALERT) {
      const severity = parameters.severity as string;
      switch (severity) {
        case 'EMERGENCY':
          return HealthMetricsRiskLevel.CRITICAL;
        case 'CRITICAL':
          return HealthMetricsRiskLevel.HIGH;
        case 'WARNING':
          return HealthMetricsRiskLevel.MEDIUM;
        default:
          return HealthMetricsRiskLevel.LOW;
      }
    }

    return HealthMetricsRiskLevel.MEDIUM;
  }

  // ===== CONVERSATIONAL VALIDATION =====

  /**
   * Perform conversational validation with Parlant
   */
  private async performConversationalValidation(
    context: HealthMetricsValidationContext,
    riskAssessment: RiskAssessment,
  ): Promise<HealthMetricsValidationResult> {
    const session = await this.parlantClient.createValidationSession({
      operationType: context.operationType,
      riskLevel: context.riskLevel,
      parameters: context.parameters,
      systemContext: context.systemContext,
    });

    // For low-risk operations, auto-approve with minimal validation
    if (riskAssessment.level === HealthMetricsRiskLevel.LOW) {
      return this.createApprovedValidation(context, session.id, 'Low risk operation auto-approved');
    }

    // For higher-risk operations, perform conversational validation
    const validation = await session.validate();
    const explanation = await session.explainAction();

    const result: HealthMetricsValidationResult = {
      approved: validation.approved,
      riskLevel: riskAssessment.level,
      conversationId: session.id,
      reason: validation.reason,
      recommendations: this.generateRecommendations(context, riskAssessment),
      auditTrail: {
        operationId: context.operationId,
        timestamp: new Date(),
        validator: 'ParlantHealthMetricsValidationService',
        decision: validation.approved ? 'APPROVED' : 'REJECTED',
        reasoning: explanation,
        evidence: {
          riskLevel: riskAssessment.level,
          factors: riskAssessment.factors,
          systemContext: context.systemContext,
        },
      },
      performanceImpact: {
        validationDuration: 0, // Will be filled by caller
        cacheHit: false,
        optimization: 'conversational_validation',
      },
    };

    // Log audit trail
    await session.logAudit(result.auditTrail);

    return result;
  }

  /**
   * Perform optimized validation for high-frequency, low-risk operations
   */
  private performOptimizedValidation(
    operationId: string,
    operationType: MetricsOperationType,
    parameters: Record<string, unknown>,
  ): HealthMetricsValidationResult {
    return {
      approved: true,
      riskLevel: HealthMetricsRiskLevel.LOW,
      conversationId: `optimized_${operationId}`,
      reason: 'High-frequency, low-risk operation - optimized approval',
      recommendations: ['Continue monitoring for patterns'],
      auditTrail: {
        operationId,
        timestamp: new Date(),
        validator: 'ParlantHealthMetricsValidationService',
        decision: 'APPROVED',
        reasoning: 'Optimized validation for high-frequency metrics operation',
        evidence: {
          operationType,
          parameters,
          optimization: 'high_frequency_fast_path',
        },
      },
      performanceImpact: {
        validationDuration: 1, // Sub-millisecond for optimized path
        cacheHit: false,
        optimization: 'fast_path_approval',
      },
    };
  }

  // ===== HELPER METHODS =====

  /**
   * Initialize operation risk mappings
   */
  private initializeRiskMappings(): void {
    // Health operation risk levels
    this.operationRiskMap.set(HealthOperationType.BASIC_HEALTH_CHECK, HealthMetricsRiskLevel.LOW);
    this.operationRiskMap.set(HealthOperationType.LIVENESS_PROBE, HealthMetricsRiskLevel.LOW);
    this.operationRiskMap.set(HealthOperationType.READINESS_PROBE, HealthMetricsRiskLevel.MEDIUM);
    this.operationRiskMap.set(HealthOperationType.STARTUP_PROBE, HealthMetricsRiskLevel.MEDIUM);
    this.operationRiskMap.set(HealthOperationType.DETAILED_STATUS, HealthMetricsRiskLevel.MEDIUM);
    this.operationRiskMap.set(HealthOperationType.DATABASE_HEALTH, HealthMetricsRiskLevel.HIGH);
    this.operationRiskMap.set(HealthOperationType.EXTERNAL_SERVICES, HealthMetricsRiskLevel.HIGH);
    this.operationRiskMap.set(HealthOperationType.SYSTEM_RESOURCES, HealthMetricsRiskLevel.MEDIUM);

    // Metrics operation risk levels
    this.operationRiskMap.set(MetricsOperationType.PROMETHEUS_COLLECTION, HealthMetricsRiskLevel.LOW);
    this.operationRiskMap.set(MetricsOperationType.API_REQUEST_TRACKING, HealthMetricsRiskLevel.LOW);
    this.operationRiskMap.set(MetricsOperationType.SYSTEM_METRICS, HealthMetricsRiskLevel.LOW);
    this.operationRiskMap.set(MetricsOperationType.DATABASE_METRICS, HealthMetricsRiskLevel.MEDIUM);
    this.operationRiskMap.set(MetricsOperationType.PERFORMANCE_BASELINE, HealthMetricsRiskLevel.MEDIUM);

    // Alert operation risk levels
    this.operationRiskMap.set(AlertOperationType.CREATE_ALERT, HealthMetricsRiskLevel.MEDIUM);
    this.operationRiskMap.set(AlertOperationType.EMERGENCY_NOTIFICATION, HealthMetricsRiskLevel.CRITICAL);
    this.operationRiskMap.set(AlertOperationType.ESCALATE_ALERT, HealthMetricsRiskLevel.HIGH);

    this.logger.debug('Operation risk mappings initialized', {
      totalMappings: this.operationRiskMap.size,
    });
  }

  /**
   * Get current system context
   */
  private async getSystemContext(): Promise<HealthMetricsValidationContext['systemContext']> {
    // In production, this would query actual system status
    return {
      currentHealth: 'HEALTHY',
      activeAlerts: 0,
      systemLoad: 25,
      criticalOperationsActive: false,
    };
  }

  /**
   * Determine operation frequency
   */
  private determineOperationFrequency(
    operationType: HealthOperationType | MetricsOperationType | AlertOperationType,
  ): 'once' | 'periodic' | 'high-frequency' {
    const highFrequencyOps = [
      HealthOperationType.BASIC_HEALTH_CHECK,
      HealthOperationType.LIVENESS_PROBE,
      MetricsOperationType.API_REQUEST_TRACKING,
      MetricsOperationType.SYSTEM_METRICS,
    ];

    if (highFrequencyOps.includes(operationType as any)) {
      return 'high-frequency';
    }

    const periodicOps = [
      HealthOperationType.READINESS_PROBE,
      HealthOperationType.DETAILED_STATUS,
      MetricsOperationType.PROMETHEUS_COLLECTION,
    ];

    if (periodicOps.includes(operationType as any)) {
      return 'periodic';
    }

    return 'once';
  }

  /**
   * Check if operation is high frequency
   */
  private isHighFrequencyOperation(operationType: MetricsOperationType): boolean {
    const highFrequencyOps = [
      MetricsOperationType.API_REQUEST_TRACKING,
      MetricsOperationType.SYSTEM_METRICS,
      MetricsOperationType.WEBSOCKET_METRICS,
    ];

    return highFrequencyOps.includes(operationType);
  }

  /**
   * Generate cache key for validation
   */
  private generateCacheKey(
    operationType: HealthOperationType | MetricsOperationType | AlertOperationType,
    parameters: Record<string, unknown>,
    riskLevel: HealthMetricsRiskLevel,
  ): string {
    const paramHash = JSON.stringify(parameters);
    return `${operationType}_${riskLevel}_${btoa(paramHash).substring(0, 16)}`;
  }

  /**
   * Get cached validation result
   */
  private getCachedValidation(cacheKey: string): HealthMetricsValidationResult | null {
    const cached = this.validationCache.get(cacheKey);

    if (cached && cached.expiry > new Date()) {
      cached.hitCount++;
      return cached.result;
    }

    if (cached) {
      this.validationCache.delete(cacheKey);
    }

    return null;
  }

  /**
   * Cache validation result
   */
  private cacheValidation(cacheKey: string, result: HealthMetricsValidationResult): void {
    const expiryMinutes = result.riskLevel === HealthMetricsRiskLevel.LOW ? 15 : 5;
    const expiry = new Date(Date.now() + expiryMinutes * 60 * 1000);

    this.validationCache.set(cacheKey, {
      result,
      expiry,
      hitCount: 0,
    });
  }

  /**
   * Check if validation should be cached
   */
  private shouldCacheValidation(
    operationType: HealthOperationType | MetricsOperationType | AlertOperationType,
    riskLevel: HealthMetricsRiskLevel,
  ): boolean {
    // Cache low-risk, high-frequency operations
    return riskLevel === HealthMetricsRiskLevel.LOW || 
           this.determineOperationFrequency(operationType) === 'high-frequency';
  }

  /**
   * Create approved validation result
   */
  private createApprovedValidation(
    context: HealthMetricsValidationContext,
    conversationId: string,
    reason: string,
  ): HealthMetricsValidationResult {
    return {
      approved: true,
      riskLevel: context.riskLevel,
      conversationId,
      reason,
      recommendations: ['Operation approved - continue monitoring'],
      auditTrail: {
        operationId: context.operationId,
        timestamp: new Date(),
        validator: 'ParlantHealthMetricsValidationService',
        decision: 'APPROVED',
        reasoning: reason,
        evidence: {
          riskLevel: context.riskLevel,
          systemContext: context.systemContext,
        },
      },
      performanceImpact: {
        validationDuration: 0,
        cacheHit: false,
        optimization: 'auto_approval',
      },
    };
  }

  /**
   * Create failsafe validation for error scenarios
   */
  private createFailsafeValidation(
    operationId: string,
    operationType: HealthOperationType | MetricsOperationType | AlertOperationType,
    errorMessage: string,
  ): HealthMetricsValidationResult {
    // For health operations, allow failsafe approval to prevent system disruption
    const isHealthOperation = Object.values(HealthOperationType).includes(operationType as HealthOperationType);
    const approved = isHealthOperation;

    return {
      approved,
      riskLevel: HealthMetricsRiskLevel.HIGH,
      conversationId: `failsafe_${operationId}`,
      reason: approved 
        ? `Failsafe approval for health operation: ${errorMessage}`
        : `Validation failed, operation rejected: ${errorMessage}`,
      recommendations: [
        'Review validation system health',
        'Check Parlant service connectivity',
        'Monitor system for patterns',
      ],
      auditTrail: {
        operationId,
        timestamp: new Date(),
        validator: 'ParlantHealthMetricsValidationService',
        decision: approved ? 'APPROVED' : 'REJECTED',
        reasoning: `Failsafe validation triggered due to error: ${errorMessage}`,
        evidence: {
          error: errorMessage,
          failsafeMode: true,
          operationType,
        },
      },
      performanceImpact: {
        validationDuration: 0,
        cacheHit: false,
        optimization: 'failsafe_mode',
      },
    };
  }

  /**
   * Generate recommendations based on validation context
   */
  private generateRecommendations(
    context: HealthMetricsValidationContext,
    riskAssessment: RiskAssessment,
  ): string[] {
    const recommendations: string[] = [];

    if (riskAssessment.level === HealthMetricsRiskLevel.HIGH || riskAssessment.level === HealthMetricsRiskLevel.CRITICAL) {
      recommendations.push('Monitor operation closely for unexpected behavior');
      recommendations.push('Review system impact after operation completion');
    }

    if (context.systemContext.activeAlerts > 0) {
      recommendations.push('Consider current system alerts when evaluating operation impact');
    }

    if (context.systemContext.systemLoad > 80) {
      recommendations.push('System load is high - consider deferring non-critical operations');
    }

    if (context.metadata.frequency === 'high-frequency') {
      recommendations.push('Optimize validation for high-frequency operations');
    }

    return recommendations;
  }

  /**
   * Update validation performance metrics
   */
  private updateValidationMetrics(duration: number, cacheHit: boolean, approved: boolean): void {
    this.validationMetrics.totalValidations++;

    if (cacheHit) {
      this.validationMetrics.cacheHits++;
    }

    if (approved) {
      this.validationMetrics.approvalRate = 
        (this.validationMetrics.approvalRate * (this.validationMetrics.totalValidations - 1) + 1) / 
        this.validationMetrics.totalValidations;
    }

    this.validationMetrics.averageValidationTime = 
      (this.validationMetrics.averageValidationTime * (this.validationMetrics.totalValidations - 1) + duration) / 
      this.validationMetrics.totalValidations;
  }

  // ===== MONITORING & METRICS =====

  /**
   * Get validation service performance metrics
   */
  getValidationMetrics(): {
    totalValidations: number;
    cacheHits: number;
    cacheHitRate: number;
    approvalRate: number;
    averageValidationTime: number;
    activeCacheEntries: number;
  } {
    return {
      ...this.validationMetrics,
      cacheHitRate: this.validationMetrics.totalValidations > 0 
        ? this.validationMetrics.cacheHits / this.validationMetrics.totalValidations 
        : 0,
      activeCacheEntries: this.validationCache.size,
    };
  }

  /**
   * Clear validation cache
   */
  clearValidationCache(): void {
    const entriesCleared = this.validationCache.size;
    this.validationCache.clear();

    this.logger.log(`Validation cache cleared: ${entriesCleared} entries removed`);
  }

  /**
   * Get cache status and health
   */
  getCacheStatus(): {
    size: number;
    entries: Array<{
      key: string;
      expiry: Date;
      hitCount: number;
      riskLevel: HealthMetricsRiskLevel;
    }>;
  } {
    const entries = Array.from(this.validationCache.entries()).map(([key, cached]) => ({
      key,
      expiry: cached.expiry,
      hitCount: cached.hitCount,
      riskLevel: cached.result.riskLevel,
    }));

    return {
      size: this.validationCache.size,
      entries,
    };
  }
}

